/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170313-3","meetingId":"h29-c-budget","date":"2017年3月13日","dateIso":"2017-03-13","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","topics":[{"id":"topic-01","title":"平成２９年度品川区一般会計予算","agenda":"平成２９年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２８９ページ、カラス・外来種対策事業の中のカラス対策と外来種のことについてお伺いいたします。それと３０５ページ、しながわ百景ウォーキングマップ作成のことを質問します。初めに、カラス、それと外来種についてお伺いいたします。このカラス、最近、私、見る限り、すごく少なくなっているのかなと考えています。よろしくお願いします。","respondent":"三ツ橋環境課長","answer":"そちらは公共の場所での動物のご相談など、この関係に関しまして、お電話のお問い合わせを受け付けておりまして、その後、対策です、カラスの巣の撤去、また外来種などの箱穴設置などに向けて対応しております。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"都内に生息しているのは、カラスの種類の中ではハシブトガラスが多いかと思うのですけれども、カラスの生態系は、夜集まって、集団ねぐらをするということで、これがどこにあるかというのはわかるかどうか、いろいろなところで生息していると思うのですけれども、これからの時期、カラスは繁殖期が３月下旬から７月下旬ということで、これから巣をつくって卵を産んでヒナを育てるということで、これから。","respondent":"三ツ橋環境課長","answer":"こちらにつきまして、平成２９年１月末現在の累計ですが、目撃情報が７８件、箱穴設置数が１１件、そして捕獲件数が３件となっておりまして、平成２７年度も捕獲件数は３件となっておりますので、大体昨年並みとなっております。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひこれは、目撃情報とかには迅速に対応していただきたいと思います。今後ともよろしくお願いいたします。続きまして、しながわ百景についてお伺いいたします。このしながわ百景、本年新しくなったということで、これからウォーキングマップの作成があると思いますけれども、この取組みというか、この作成の内容をどういうふうに事業としてやっていくのかお知らせいただきたいと思います。","respondent":"鈴木文化観光課長","answer":"中身としましては、日本語、英語、中国語、韓国語の４カ国語で、それぞれ１万部ずつをつくりまして、ただ配るだけではなくて、他の観光事業との連携やお勧めのコースなどを設定して活用いただくということで考えております。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"すみません、これ、前後しますけれども、しながわ百景ウォーキングマップ作成についてというか、これは３０年ぶりにリニューアルをしたということで、たしか４０周年のときに、しながわ百景のプレートを設置していると思うのですけれども、それも含めて新しくそういったプレートもこれから設置をするのかどうか、お聞かせいただきたいと思います。よろしくお願いします。","respondent":"中島企画部副参事、中元広報広聴課長","answer":"しながわ百景のＡＲについてお尋ねがございました。今後、ＡＲ技術（拡張現実）というＩＣＴ技術を活用いたしましてＰＲをしてまいりますが、その主要なスポット１０カ所程度で撮影スポットを考えております。しながわ百景で新しく選びましたプレートの件ですけれども、そちらも現地の方、施設管理者の方と調整をさせていただいて、できる限りプレートをつける形で検討しています。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"しながわ百景、１２カ所増えたと思うのですけれども、その１２カ所は全部プレートを設置を検討していくのかどうか、そこだけお知らせいただきたいと思います。よろしくお願いします。","respondent":"中元広報広聴課長","answer":"１２カ所につきましては、こちらとしては検討しています。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問・要望","question":"２７３ページ、ＡＥＤ管理費、２７９ページ、母子健康診査費、２８１ページ、産後ケア事業、２９１ページ、もったいないプロジェクト等、３０５ページ、都市型観光プラン推進事業について伺っていきたいと思います。３００メートルごとの整備、なかなか難しい地域においても、いろいろな工夫をして推進していただきたいと思います。リンクを張った経緯と、それをどう活用していくかを教えてください。","respondent":"川島健康課長","answer":"ただいまのリンクを張りました経緯ですが、まず、一般質問の中で、つる委員にご紹介いただいたというところで、中をいろいろ見てみますと、非常に役に立ちそうだということで、気軽にまず救急救命はどうするのか、それからＡＥＤの使い方。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな区民相談も含めて要望があって、当初それをやるかもしれないということであったので、一応、私のほうから訂正しますが、要望はさせていただいていたということで、その「減らせ突然死プロジェクト」の中で、これはすごい積極的に活用を区としてもやっていただきたいと思うものが、その中に「心止村湯けむり事件簿」というのが入っております。","respondent":"川島健康課長","answer":"その辺のご紹介も我々の役目だと考えていますので、今後、検討してまいりたいと考えています。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"今まさに審議中だと思うのですが、これは一定の要件として、産後ケア事業を自治体として行っているところが使えますという形だと思うのですが、品川区はもう既に産後ケア事業を行っていらっしゃるわけですから、これがしっかりと予算が通った際に、この産婦健康診査事業を導入すべきだと思うのですが、この辺の考え方、もう既に予算の中に反映されているのであれば教えていただければと思います。","respondent":"太田品川保健センター所長","answer":"考え方につきましては、産後健診の助成につきましては、現在、妊婦健診が都内医療機関の２３区相互乗り入れで、１４回分の公費助成を行っておりますので、その仕組みと同様にできることが利用者の利便性のために好ましいと思われますので。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"国と自治体で２分の１ずつという費用の配分だと思います。それを経由して区市町村の取組みを支援する、そうした流れということで私も伺っております。これまでも求めてまいりましたが、こうした動きも含めて、早期発見、早期療育のために、区としても積極的にその体制の充実を東京都に求めるべきかと思いますが、現在の働きかけの状況等を含めて教えてください。","respondent":"太田品川保健センター所長","answer":"その結果が出たところで、２３区相互乗り入れの新生児聴覚スクリーニングを行うかどうかという検討に進んでいくかと思いますので、そちらの状況を見て品川区としての方針を決めていきたいと考えています。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"次に移ります。産後ケア事業です。補正のときにもちょっと伺ったのですが、改めて、平成２８年度の日帰りのケア、それからホテルの利用状況を教えてください。","respondent":"榎本荏原保健センター所長","answer":"産後ケア日帰り型事業の利用状況です。６月から開始したわけですが、６月から２月までで、約８０名の方が利用されました。利用率ですが、６５％です。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"ごめんなさい、聞き方を間違えました。ホテルを使って、宿泊型についても教えてください。失礼しました。","respondent":"太田品川保健センター所長","answer":"医療機関を利用した宿泊型の利用状況ですが、１１月から予約を開始し、１２月から宿泊を行いまして、２月末で１６件の利用が行われている状況であります。","id":"exchange-011"},{"speaker":"つる委員","kind":"確認","question":"今、数字を改めて伺ったのですが、いずれにしても、これは初産の方が対象になっていて、前回も確認しましたが、初産の方の１０％ということであるわけでありますが、近年３年間の出生数の平均が３,５８０で、そのうち６割の方が初産ということで、この間ご答弁いただいたことをあれすると、約２,１５０ぐらいが対象になるかと思う中で、１０％というと２１５ぐらいとなると、今お聞きした数字が。","respondent":"榎本荏原保健センター所長、太田品川保健センター所長","answer":"産後２カ月ぐらいまでということで、当初、対象を考えていたのですが、里帰りをしてご利用される方も４３％ぐらいございましたので、その期間につきましても、４カ月未満ということで拡大をしていく予定です。宿泊型に関しては、日帰り型に比べてもう少しハイリスクな妊婦を対象にしておりますので、やはり産後うつになられた方の８割が初産婦であったということから、初産婦の方を対象にと考えています。","id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"日帰りについては、第二子以降、また２カ月から４カ月の間ということで、ありがとうあります。改めて宿泊型については伺っていきたいと思います。もったいないプロジェクト等なのですが、これ、昨年の建設委員会に私が所属しているときにも、２回ほど提案も含めてさせていただいたものでありますが、食品ロス削減、それに加えて、発展途上国の支援にもつながるという取組みを紹介させていただきました。","respondent":"三ツ橋環境課長","answer":"こういったようなことを含めて、ドギーバッグにつきましては、衛生面でなかなか慎重にならなければいけない問題と捉えておりますので、いろいろほかの部分も勘案しながら慎重に考えてまいりたいと考えています。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"私も自分が使っている名刺入れが、「Signature for Good」と言って、それを買うと開発途上国の子どもたちの教育とか識字率の向上の支援に使ってもらえるということで、そういった文具を使っているわけなのですが、こういうドギーバッグは食品ロスを削減できて、なおかつ、そういう発展途上国の支援にもなるということでは、さまざまな観点からも非常にいい取組みかと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる住宅リフォーム助成の中に、中小企業と商店版ですが、まちのにぎわいに向けた商店や中小企業への支援強化として、そして地元の仕事づくりにもつなげていくこうした内装や外装改修への補助制度について、区はこれまで融資制度を利用と説明しておりますが、より積極的に補助制度導入へとレベルアップを求めますが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"私ども区といたしましては、商店街に対しましての助成、支援につきましては、さまざま対応しています。それぞれ個店への住宅リフォーム助成などの直接的な支援はございませんが、例えば、一定の条件のもと、店舗建物におきまして住宅の部分と店舗の部分があります。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"こうした業態が活気にあふれていなければ、品川区の継続的な発展はなし得ないと、中小企業と商店街を積極的に位置づけていると思います。にぎわいや活性化の名で再開発への補助制度は重要と、さまざまなメニューで補助制度がありますが、なぜ中小企業や商店に対しては、建物への補助制度メニューではなくて、いわゆる融資制度で十分だと考えるのか、その理由を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"こういう意味では、それぞれ個店のお持ち物としての建物でありますとか、そういったところに直接貴重な区民の方々の税金をどの程度投入すればいいのかというようなこともございまして、現在は、商店街、ゾーンとしての支援、あるいは、中小企業であれば。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"個店は経済活動をしているからというお話がありましたけれども、再開発のオフィスビルもすごく経済活動をしていると思います。例えば、個人住宅の耐震化についても、安全なまちづくりに資するということで補助制度があります。施政方針でそこまで中小企業や商店街を位置づけているわけですから、ぜひ中小企業や商店街の内装や外装に補助制度を導入することを改めて強く求めますけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"産業支援と再開発で一概に比較してというようなことは少し難しいご質問かとは思いますが、いずれにしましても、再開発もそうした事業を行うことで、周辺の地域にもたらす社会貢献の意味合い、こうした公的な性格を有するものに、区、行政は補助ができると。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"そしてあわせて、商店街イベント告知チラシの補助制度も伺いたいと思いますが、東京都は、商店街のイベント告知チラシへの補助について、平成２９年度も、いまだに次回告知など、ほかの内容が入ったものは補助対象から外しているのかどうか、まずこの事実を伺いたいのと、区は、東京都に改善を求めているということですけれども、東京都が改善するまでの間、商店街の負担にするのではなくて。","respondent":"山崎商業・ものづくり課長","answer":"こちらについては、区の申し入れもあり、イベント実施商店街が主催する当該事業以外の情報であっても、チラシの面積１割の部分であれば告知ができるということで改善をしていますので、平成２９年度は、それはそうした取組みでやってまいりたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"商店街や中小企業はとても地域経済に貢献していると思います。とりわけ経済の多くは個人消費ですから、そこをしっかりと見ていただいて、実施を改めて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"しながわ観光大使に関しては、これはサンリオが品川区に本社を有しているということで、いろいろ連携の中でシナモロールが事実上のキャラクターであって、シナモロールと品川区の観光大使は同じ名前ということだと思うのですけれども、要するに、せっかくこういった夢の世界のキャラクターが観光大使になったということで、いろいろと話題性とか、ストーリー性を考えていかなければいけないと思って、例えば。","respondent":"溝口公園課長、鈴木文化観光課長、中元広報広聴課長","answer":"続きまして、西大井駅前の公衆便所につきましては、設置からもう３０年以上経過して古くなっているという認識があります。その後につきましても、今、観光振興協議会で検討いただいている有効なスポットを優先的に設置をしていきたいというふうに考えておりますが。総務費のほうで入っておりますデジタルサイネージのシステム構築ですが、こちらは主に区有施設内にデジタルサイネージを設置いたしまして。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"生垣が増えれば緑被率が増える。それは災害にも有効、震災が起きたときの火災にも有効になってくると思いますので、これは５件の見積もりになっているのですけれども、やはり連携をして、特に地震が来たときは、塀の倒壊の可能性はいくら新しくつくったものであっても、可能性はあるわけですから、できる限り、緑化を進めていくよう努力をしていただきたいと思います。多分、１体しかないわけですから。","respondent":"鈴木文化観光課長","answer":"任命されたことのアピールですが、既にサンリオのほうでも取り組んでいただいていまして、サンリオの「いちご新聞」などで紹介をしていただいております。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、２８８ページの環境対策費、２８９ページの航空機騒音調査に関連して、羽田新ルート案についてお伺いをいたします。世界の都市総合力ランキングがあります。ですから、この政府の政策目標が達成できない可能性もあるのですけれども、こういったことをしっかりと国土交通省にお伝えをしていただき、１回立ちどまって考えていただきたいのですけれども、品川区のお考えはいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"したがいまして、委員ご指摘のように、さまざまな要因が考えられますので、それは政府として考えていることだと思います。しかしながら、品川区として影響がある場合には、国に申し伝えてまいります。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"当然、船ですから、普通の建物と違って遮る壁が一切ありません。ですから、しっかりとこうした品川区は都市型観光プランとして舟運事業、水辺活用を非常に重視している。したがって、新飛行ルート案の実現で観光資源が著しく損なわれるという恐れが非常にあるということを、ぜひとも国土交通省にお伝えしていただきたいのですけれども、品川区のお考えはいかがでしょうか。","respondent":"中村都市計画課長","answer":"そういった関係からは、この機能強化については理解するけれども、ただ、やはり品川区として影響があるというところにつきましては、必要な対応について国に強く求めてまいるというふうに考えているところです。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"国土交通省は、品川区は都市型観光プランとして、舟運事業や水辺活用事業を重視しているということはご存じなのでしょうか。","respondent":"中村都市計画課長","answer":"その中には、当然、品川区としては観光を重視していること、にぎわいの増加を重視していること、こういったことはたびたび伝えているところです。委員がおっしゃいました国への要望、これは引き続き強く求めていきたいというふうに考えております。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"特に成田空港の活用をぜひとも考えていっていただきたいと考えております。品川区以外でも、ほかの区でもこうしたバス路線を拡充していけば、今回のように反対の声を押し切って無理に新飛行ルート案を実現するより、ほかの代替案をしっかりと考えるべきだと考えていますし、品川区としても、そういったことを伝えるべきだと考えておりますけれども、その点、お考えはいかがでしょうか。","respondent":"鈴木文化観光課長","answer":"確かに上空を飛ぶ飛行機の音は船でも聞こえるような形になりますが、実は、その船に乗って低空を飛ぶ、または空港から飛び出すところの飛行機を下から見るというツアーも意外に人気がありまして、全て飛行機の新ルートが観光に。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"船に乗って飛行機を見るのが楽しいと感じる人がどのぐらい人数がいるか、あと、本当に静かな環境で水辺環境を楽しみたい人が、どちらが多いかという比較論になっていきますので、だから、そうした声、アンケートもしっかりとっていただきたいのですけれども、そういうアイデアがおありでしたら、ぜひ区民の皆様の声をとっていっていただきたいと思いますけれども、その辺はいかがでしょうか。","respondent":"鈴木文化観光課長","answer":"ご指摘のように全ての方が飛行機を見るのが好きということではございませんが、静かに桜を見るツアーのときは、またそういう方に向けたコース、飛行機を見たい方は水辺で特に羽田方面というように、それぞれ訪れる方のお好みとか希望に合わせたコースを用意して。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"今回の新飛行ルート案は、こちらの事情は考慮せず、１５時から１９時に一方的に通ってしまう可能性が大きいものですから、桜を見るというときも飛行機が上をがんがん飛んでいるかもしれませんので、とにかく飛ばないに越したことはないのですから、ぜひとも品川区としても強くそうした品川区の事情を言っていっていただきたいと考えております。","respondent":"中村都市計画課長","answer":"新ルート案については、これは国に対してしっかりと要望してまいりますけれども、これとは別に、新線ですとか、公共交通の拡充、こういったものも並行して進めていくべきだと考えております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"いろいろな案が考えられますので、ぜひとも国土交通省に１回立ちどまって考えていただきたいということで、しっかりと品川区の状況をお示ししていただきたいと考えております。やはり私としては、今、新ルート案で考えられることは、メリットよりデメリットのほうが多すぎますので、今の段階で反対の表明を品川区として行っていくべきだと考えておりますけれども、その点はいかがでしょうか。","respondent":"中村都市計画課長","answer":"今回の新ルート案につきましては、国からも経済波及効果の試算も出されておりますが、これについても区としての直接的な影響についても不明確ですし、また、その他メリット、デメリット、こういったものもさまざまな角度から検討する必要があると考えております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"意見","question":"よくご答弁では、案の段階だからとおっしゃるのですけれども、決定してからでは利害関係者や費用の面でも既成事実が積み重なってしまっておりますので、もう反対しにくい状況、非常に遅いという状況なので、早め早めに品川区の状況を伝えて、向こうの対応次第では反対の表明をすべきだと考えておりますので、ぜひともその点、よろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"横山委員","kind":"確認","question":"私からは、２７７ページ、乳がん検診、２８５ページ、不妊治療費助成、３１１ページ、品川技術ブランドＰＲ事業、商店街国際化推進事業、３１３ページ、海外進出推進事業、情報通信業等の企業間連携支援についてをお伺いいたします。先日、たけうち委員より、乳がん検診に関する質問がありましたが、まず初めに、乳がん検診率の推移について、最近の傾向を確認させてください。","respondent":"川島健康課長","answer":"最近の乳がんの検診の実績ですが、平成２５年度が９,９５６人、平成２６年度が９,５０１人、平成２７年度が１万８０５人ということで、平成２８年度は平成２７年度を超えるような受診者数となっておりまして、今お尋ねの受診率で言いますと。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"検診率が大幅にアップしているということをお聞きいたしました。そこで、授乳期と断乳後６カ月未満の方の乳がん検診について、現在の区の状況を教えてください。３５歳、３７歳、３９歳で断乳のタイミングが訪れた際も検診を先送りせず、次の検診の前に受診をしていただきたいと考えているのですけれども、区のご所見をお聞かせください。","respondent":"川島健康課長","answer":"委員お尋ねの授乳期、断乳後６カ月未満の方の乳がん検診の対応ですが、広くがんの有無をスクリーニングするという区のがん検診におきましては、授乳期等は通常の体の状況とは違うということで、乳腺外科のご受診をということを今はお勧めしています。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"こちら、受診券と同封の「あなたを乳がんから守る検診のご案内」と、品川区のウエブサイトには、受診できない方に関するご注意ということで記載がありますが、妊娠から授乳期の取扱いについては、早期発見、受診率アップにつながるように、詳細のご案内を載せていただくとともに、助産師、保健師、ネウボラ相談員への情報提供や。","respondent":"川島健康課長","answer":"今のご質問にあったようなご案内の徹底というところですが、どのようにしていけばいいのか、今後引き続き努力してまいりたいと考えています。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目は、不妊治療助成についてお伺いいたします。今月、男性不妊症をご専門とする獨協医科大学越谷病院の小堀先生より、佐賀県杵藤地区で実施をした産婦人科および泌尿器科医療機関職員、学校教師、保健師を対象とした講演会の事例をご紹介いただきながら、男性不妊症の意識改革と文化をつくっていくことの必要性を伺いました。","respondent":"川島健康課長","answer":"区としてもホームページを充実させること、それから、ご提案のありましたパパママ応援アプリの活用など、どうしたら男性不妊に関する啓発のあり方がよいのかというようなところも含めて周知に努めてまいりたいと考えています。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"ただ、男性の不妊治療もやはり半分ぐらいはあるという傾向をお聞きしておりますので、今後、データの分析も少し進めていただいて、クリニックの受診、なかなかプライドというのですか、お気持ちの部分とか、男性側、また女性もそうですけれども、ためらったりする部分はあるかと思うのですが、まずは不妊症の周知啓発というところからスタートしていただいて、アプリですとか、ホームページですとか。","respondent":"小川オリンピック・パラリンピック準備課長、山崎商業・ものづくり課長","answer":"新年度の予算では、適地調査費用も入っているところですので、委員のご指摘の趣旨も踏まえつつ、現段階ではあらゆる可能性を探ってまいりたいと考えているところです。現在取り組んでおります、また、これから取り組む予定の商店街ならびに産業関連の国際化推進事業などにつきまして、企業間ホスピタリティハウスなどの動向を勘案しつつ、さまざま展開している産業関連資源との連携について。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"今ご紹介をさせていただいた各事業なのですけれども、それぞれすばらしい事業かと思いますので、オリンピック・パラリンピックに向けましても、ぜひ連携をしていただいて、また、リオの視察でいろいろ実際現地に行って見てこられたという、そういった部分でしかわからないところで、今、品川区はいろいろ動いてくださっていると思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、２７９ページ、公衆便所費。２７７ページ、各種がん検診について、関連してアピアランス支援。３０５ページ、フィルムコミッション事業。時間があれば、３０３ページ、中小企業ＢＣＰ作成支援事業、もう１つが、産業経済費で、ちょっと見当たらなかったのですが、しながわみやげについて伺いたいと思います。大震災等の際に、公衆便所が果たす役割と耐震化の状況について教えてください。","respondent":"溝口公園課長","answer":"公衆便所につきましては、設置したものが古くて、なかなか災害時の対応まで行っておりませんが、今後、整備していく中では、災害時のマンホールトイレまたは地下にピットを設けて災害時対応できる、そういったトイレを整備していきたいと考えているものです。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"議会の中でもたびたびネーミングライツを利用して民間の活力をという話もあるのですが、これは一定の効果はあると思うのですけれども、この前の答弁にもありましたが、なかなか全体的に波及するかどうかということもあるでしょうし、非常に難しいかと思うのですけれども、この点、品川区は今後どのようにお考えになっているのか、女性の使用しやすいトイレ、子どもが使いやすいトイレ。","respondent":"溝口公園課長","answer":"清掃につきましては、さらに臭いとか、そういったものがあれば、高圧洗浄をかけたり、また、特別清掃、特別な薬品を使って清掃するなど、そういったことを対応しながらやってきているものです。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはりどうしても女性の場合、トイレで襲われるのではないかとか、盗撮されるのではないかという、そういう危険性があると思うのですが、赤色灯の設置とか、防犯カメラの設置ということも、各自治体で今いろいろと検討されているのですけれども、品川区の現状についてお伺いしたいのと、最後にちょっとまとめて言いますが、イメージアップです、女性が入りやすいトイレに今なっていますよということを。","respondent":"溝口公園課長","answer":"さらには、最近ですと、観光マップ、またはウォーキングマップ、そういったところにもトイレの紹介をさせていただいているところではあります。引き続き、品川区のトイレが利用しやすい効果的なＰＲ方法については検討していきたいと考えているものです。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いわゆるウィッグには人間の人毛が一番いいということで、その方もそういったウィッグをつけられていたということで発信をされて非常に反響を呼んでいるということもありますが、調べてみると、品川区内の美容室にもそういうヘアドネーションの協力をされている美容室も６つくらい見つけましたけれども、そういったことを、今後。","respondent":"川島健康課長","answer":"委員よりご提案のございましたアピアランス支援の中でのヘアドネーション制度等、がん患者が社会生活を送る上での有効な支援策の１つというふうに考えてあります。どういった形で区の施策に取り入れていけるのか、今後しっかり検討させていただきたいと思います。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"提案","question":"フィルムコミッションを成功させるためには、やはり熱い情熱を持って事に当たれる人間、これは皆さんそうだと思うのですけれども、だめでもともとと思いながら飛び込んでいける営業能力、こういうことが必要になってくると思うのですが、もちろん優秀な品川区の皆さんですから、皆さんそうだと思うのですが、ぜひそういう職員の方の配置をお願いしたいと思うのですが、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"ほかの部会でも観光資源の検討をいただいていますので、その情報もあわせながら、区として正式なフィルムコミッションの担当の部署を設置しまして、しっかりと調査やＰＲを進めていきたいと考えております。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ、これは要望になりますが、シビックプライドの醸成のために、各フィルムコミッションでやっているのが、市民の方、区民の方にボランティアでエキストラに参加をしていただくということをやっております。これは永久にフィルムは残りますから、そこに区民の方が参加できるということが重要だと思いますので、ぜひこういったことも検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"最初に、３０５ページの第５款１項産業経済費から、就業支援費の中の就業支援事業を伺いたいと思います。実績が伸びているというふうに判断しましたが、ここでお尋ねしたいのは１点だけです。継続して伺っておりますが、子育て中の女性の相談のための保育の体制、昨年もお尋ねしているのですが、研究課題とするということでしたが、その後、検討は進んだか、その点だけ教えてください。","respondent":"立木産業活性化担当課長","answer":"子育て中の女性の就労相談の件ですけれども、今現在も引き続き検討している最中です。場所は託児室が中小企業センターにあります。来られない方に対しての相談ということで、出張相談も来年度検討させていただきたいというところで、今さまざまな角度から検討している最中です。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"ちょっと飛びます。２８８ページの環境費、環境調査測定費、先ほどもご質問ありましたけれども、航空機騒音調査が増額になっております。どのような趣旨での増額か伺いたいと思います。どういう調査なのでしょうか。どういう建物を想定しているのか、公共の建物だと、あまり高いビルはないように思うのですけれども、民間の高層ビルの屋上なども測定可能なのか、お答えください。","respondent":"三ツ橋環境課長","answer":"こちらは６００ｍメッシュを切って、それぞれ約５０カ所の地点を騒音調査していく予定です。一方、吉田委員のご指摘の屋上の部分に設置という部分ですけれども、こちらは基本的に公共の機関の建物を考えておりまして、例えば、区役所の屋上などを考えております。","id":"exchange-043"},{"speaker":"吉田委員","kind":"確認","question":"前は、国の調査地点と調整するようなお答えだったのですが、これは区の独自のポイントを決めていくというふうに考えてよろしいのでしょうか。それを１点確認させてください。共鳴とかそういうものは難しいというご答弁だったのですけれども、少なくとも高層ビルの調査は必要なのではないかと思いますが、その辺はどのようにお考えか教えてください。","respondent":"三ツ橋環境課長","answer":"屋上の部分ですけれども、確かに委員おっしゃるように、普通の地面と高さというのは聞こえ方が非常に違いますので、そちらの部分に関しては、いろいろ情報を仕入れながら国からの情報を伺いながら対応してまいりたいと考えています。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"一般質問の中で、他の会派の方が取り上げられたＮＨＫのニュースで、成田空港での落下物のことを取り上げたニュースを私も見ました。その点について見解をいただきたいのと、それから、あのニュースを見て大変気になったのは、２回やったのです。「おはよう日本」でもやりました。今まで私たち、院内集会で確認したところでも、まだ決定ではない。その辺、もう一度確認させてください。","respondent":"三ツ橋環境課長","answer":"したがいまして、引き続き、丁寧な説明、また区民に対する説明会なども実施を要望してまいりますので、区民の皆様の不安払拭に向けて対応してまいります。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"決定ではないということを確認させていただきました。品川区としてきちんと反対をしておかないと、もし何かあった場合には、それは国の問題だということでは区民は納得しないと思いますので、その辺をぜひ反対の表明をしていただきたいと思います。次に、２９７ページ、３項清掃費、１目清掃総務費の東京二十三区清掃一部事務組合分担金について伺います。それから、増額の根拠もあわせて教えてください。","respondent":"小林品川区清掃事務所長","answer":"品川区の場合、現状、毎月大体１億円、来年はそれが総経費で年間１億円ほど増加している、その理由ですけれども、基本的には、工場の建替え等による設備費が計画修繕も含めまして、来年度の事業費が膨らんだために、各区の分担金が増加しています。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"搬入しているごみの量が、この分担金に関係してくるということであれば、例えば、区民がごみの減量をするとか、もったいないプロジェクトとかもありますから、そういうことで減っていけば、これは減らすことができると考えてよろしいのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"ただ、にわかにごみ量が増えたとしても、固定施設として持っている清掃工場等の経費の負担は、基本的に大きく変わることができませんので、短期的にすぐに各区のごみ量の増減で変わってくるというものではございません。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。その質問は一旦そこで打ち切って、先日もちょっと話題が出ました。ＪＩＣＡから受託した事業の視察に清掃一部事務組合から行くという報道がありました。各区の議長が行かれるということなのですけれども、これ、ＪＩＣＡから受託した事業の視察ということであれば、その予算もＪＩＣＡから出ているのでしょうか。それとも各区の分担金から出るのか、それを教えてください。","respondent":"小林品川区清掃事務所長","answer":"国際協力事業として取り組む場合に、その経費につきましては、ＪＩＣＡあるいはその他の関係団体等から負担がありますので、清掃事業として費用を持ち出しているというものではありません。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"ＪＩＣＡからの受託事業本体はわかります。この視察に関しての、それも受託の中に含まれての視察なのか、それとも独自の分担金で行くものなのか、それを伺いたいのです。","respondent":"小林品川区清掃事務所長","answer":"今回、新聞報道等がございました議会として視察するというものは、これは分担金の中から編成しております一部事務組合総体の予算編成の中からのものですので、かかわりがあるのかないのかと言われれば、分担金の対象になっているというふうに理解しております。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"報道で読んだ限りなのですけれども、既に１年前に終わった事業を視察ということです。何を見にいらっしゃるのかというふうに思います。その事業内容をここで質問しても、なかなか答弁は難しいということも承知しているのですが、でも、分担金を出す以上、区としても区民に対して説明責任があるというふうに考えます。この視察の趣旨と意義を把握していらっしゃるのかということを伺いたいと思います。","respondent":"小林品川区清掃事務所長","answer":"一義的に一部事務組合として取り組むものについてご説明する立場にはないので、十分な情報を持ち合わせてはおりません。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望にしておきます。いけるところまであれなのですが、環境三計画の見直しについて伺います。この方向が進むかどうかだけ確認させてください。それとあわせて、雨水タンク、区有施設の予算が皆減になっておりますが、これはつけるべきところはみんな終わったということで、新たにそういう施設があれば、またということで考えてよろしいのでしょうか。","respondent":"三ツ橋環境課長","answer":"三計画改訂の進捗状況ですけれども、今年度につきましては、各課へのアンケート、また区民の皆様へのアンケートを集約しておりまして、方向性といたしましては、今後、三計画を整合性をとりながら改訂してまいります。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"２７７ページ、こころの健康づくり事業、２８５ページ、職員給与費、保健師の人員不足の問題を取り上げます。保健師の配置状況を教えてください。保健所、保健センターの総数、また、その他の課のところの事業に配置されている人数を、わかる範囲でいいです、それぞれ教えてください。","respondent":"太田品川保健センター所長","answer":"うち１名が短時間再任用ということになります。働いている職場と職務内容ですが、育休中の方を含めますと、高齢者福祉課に３名、国保医療年金課に１名、保健予防課に４名、保健センターには２９名配属となっております。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２５年に伺ったときには、全体で３８人でした。このとき、２３区中２３位だったわけです。１人の担当が約１万人弱だったのですけれども、その後５年間で２万５,０００人の人口増となっていますけれども、保健所、保健センターは、これでいくと、変化はないのでしょうか。高齢者、子ども、障害者の事業への保健師の配置が求められていると思いますが、この辺の認識はいかがでしょうか。","respondent":"太田品川保健センター所長","answer":"先ほど委員も述べられました措置入院後の対応が自治体の責任になるということで、これについては国のほうでも人件費を、全国ですが１０億円の予算をつけるというふうな話も上がってきておりまして、その分野について非常に人手がかかるということは認識しております。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当にいろいろな分野で健康を守っていくという立場で保健師の役割が求められてきています。拡大もどんどんされていると思います。そして、健康を増進させていくという大事なプランを立てていく健康課に保健師が１人もいないとお聞きしました。保健所、保健センター、増員が求められますけれども、現場職員の意見を取り入れて、こういった面、改善が必要であると思いますが、いかがでしょうか。","respondent":"太田品川保健センター所長","answer":"保健師の業務につきましては、どんな仕事もそうですが、緊急性の高い仕事に優先順位を高くして行っております。いろいろな虐待等、養育困難に陥った家庭への支援等におきましても、保健師１人でやるというのではなく、関係各課と協力して行っているところです。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろなところで連携をしていくのは当然であると思っていますが、本課のところの職員、保健師の仕事は多岐にわたっていますし、目の前にあらわれている緊急な事態にもちろん対応していかなければいけないけれども、実際に区民全体に目を向けて、今、問題点がどこにあって、どういった方向で新しい施策を立てていくことが区民の健康増進につながるのかといった。","respondent":"川島健康課長","answer":"保健師が健康課に配属されていないというようなところの関連だとは思うのですが、現在、先ほども品川保健センター所長がお答えしましたが、健康課と保健所で適切に連携しまして、保健師のご協力をいただいて仕事を進めているようなことですので、健康プランも保健所。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大変かみ合っていないわけです。保健師の現場の声で、兼務になっていてやり切れないと言っているのです。私、さっき確認しましたが、平成２５年のときから増えていないではないですか。私は、健康課への保健師の配置、そして全体の保健所、保健センターのところの増員を求めましたけれども、ここのところ、今の状況で十分だと考えているのか、増員を求めていますので、明確にお答えください。","respondent":"米田人事課長","answer":"保健師については、業務の内容を勘案しながら、所管と所要人員の関係等でやっております。この間、人数的にはあまり変わっていないかもしれませんけれども、非常勤職員の活用等を含めて、事業には対応しているというふうに考えてあります。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"次にいきます。こころの健康づくり事業ですけれども、自殺予防のための啓発が進んでいるのかどうか、ここを教えてください。そして、昨年、文教委員会で名古屋市に視察に伺いました。予防事業の位置づけ、強化の立場で質問をしたいと思います。「気づいてる？ぜひ予算を組んで、予防啓発パンフレット、そしてハンドブックをこの品川区でもつくっていただきたいと思いますが、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"それにつきましては、来年度も継続します。そういうふうに連携をしている中で、名古屋市に視察に行った件、パンフレットについても、情報提供をいただいております。それについては、連携しながら検討していければと思っているところです。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保健師のところの答えをいただいていません。経験の長い方が退職していく中での今後の業務維持とか発展のために早期に採用し育成、育成のところが必要ではないかということを訴えました。パンフレット、ハンドブックのところは、ぜひ教育委員会、子どもの頃からのところも、ぜひ力を入れて、前向きに連携強化していただきたいと思います。","respondent":"太田品川保健センター所長","answer":"保健師の育成については、心がけてまいります。","id":"exchange-058"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、２７３ページの予防接種費、定期予防接種と、２７５ページの感染症対策費、２７７ページの健康診査、２８１ページの出産・子育て応援事業について質問します。平成２６年１０月に定期接種となった水痘ワクチンの接種率の推移と、過去数年間の水痘（みずぼうそう）の発病者の推移に関して、もう一度、補正に引き続いてご説明をお願いします。","respondent":"舟木保健予防課長","answer":"接種率についてですが、区では、任意接種を実施してはいたのですが、そちらの実績、１回助成という形でやっておりましたので、平成２５年で３,０００人弱の方が助成を受けておりました。","id":"exchange-059"},{"speaker":"鈴木（博）委員","kind":"質問","question":"平成２６年１０月に水痘ワクチンが定期接種にされてから、かつては年間発病、推定１００万人、重症入院患者が４,０００人、死者が２０人と言われていたみずぼうそうは、今の課長のご報告のとおり、今、激減しています。みずぼうそうのワクチンの効果は、発病阻止率が８０から８５％、重症化阻止が１００％と言われており、この結果はみずぼうそうの定期接種化の効果によるものと思われます。","respondent":"舟木保健予防課長","answer":"非常に感染力が強いということで、院内感染とかでも非常に問題となっているような状況です。そういう意味では、健康小児のみずぼうそうの予防だけではなくて、そういうふうに重症化リスクの高い方を水痘から守る、そういうような効果もあるのではないかと考えています。","id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ワクチンを受けられないで治療が行われなかった悪性腫瘍の子どもの致死率（死亡率）は７％から１７％と言われています。水痘ワクチンの接種率の向上のさらなる向上と維持、区としてもしっかりと取り組むように要望いたしまして、次の質問に移ります。次は、梅毒についてお尋ねします。梅毒の流行の状況と、現在の流行はいつからどのようにして始まったのか、まずご説明をお願いしたいと思います。","respondent":"舟木保健予防課長","answer":"２０１０年以降は、報告数が継続して増加するような状況となりまして、２０１３年以降は、年間１,０００例を超えまして１,２２８例、２０１５年（平成２７年）には２,６９０例、２０１６年（平成２８年）は、４,５１８例と急増しているような状況です。","id":"exchange-061"},{"speaker":"鈴木（博）委員","kind":"質問","question":"少し古いデータですが、１９９９年の時点で世界中では１,２００万人が新しく発病したと推定されており、ＨＩＶ感染症と絡み合いながら世界中で流行が続いています。２０１５年は２,３２８例、２０１６年、去年は４,０００例を突破して倍増しています。先天梅毒も昨年は１４例報告されています。そもそも梅毒はどういう病気なのか、あるいは非常に問題になる先天梅毒について、簡単にご説明をお願いします。","respondent":"舟木保健予防課長","answer":"梅毒についての説明です。梅毒は、今おっしゃいましたように、梅毒トレポネーマという細菌が原因で起こる感染症で、慢性、急性の経過をとります。過去の病気と思われがちなのですが、今申しましたように、非常に最近、患者数が増えているような状況です。","id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"質問","question":"梅毒は、最初、感染して数週間で痛みを伴わない、接触した場所、性器だとか口腔内にしこりができて、それが破けて潰瘍になります。心臓に来て、致命的な心疾患になったりすることもあります。このような梅毒が、今非常に問題になっているわけですが、区として、現在、この大流行が始まっている梅毒に対して、どのような取組みをされているのか、ご説明をお願いします。","respondent":"舟木保健予防課長","answer":"品川区では、東京都、国が必ず６月、１２月に、エイズ、性感染症の予防月間という形で啓発事業を強化しておりますので、そのときにあわせて一緒に啓発をしたり、あるいは、月１回は、品川、荏原保健センターで性感染症の検査を実施しておりますので。","id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"質問","question":"オーラルセックス、アナルセックスその他でも感染する。厚生労働省も２０１５年に「女子の梅毒増加中」という啓発リーフレットをつくって配布したほか、「オーラルでも、うつります。！」というようなポスターの作成など、かなり必死さが伺われるような啓発活動を行っています。デング熱、チクングニア熱など、蚊媒介感染症に対する品川区の予防対策に関して、昨年に引き続いてお尋ねいたします。","respondent":"井浦生活衛生課長","answer":"経費は２,１９３万４,０００円でございまして、うち導入のための単年度経費が７６３万４,０００円、ランニングコストといたしましては、雨水マスへの薬剤投入委託が１,４００万円余です。財源としまして、都の補助金２７０万円を予定しています。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"４月からいよいよボウフラだとかが活発に活動して、成虫もだんだん見られる時期になりますので、その対策はよろしくお願いいたします。次に、成人眼科検診についてお伺いします。次年度の新規事業から成人眼科検診が見送られました。４０歳以上の眼科検診の実施を高齢者の健康寿命の延伸のために、再度ぜひ要望したいと思いますが、区のご見解はいかがでしょうか。","respondent":"川島健康課長","answer":"委員ご指摘のとおり、この検診の重要性につきましては、十分認識しています。しかしながら、先行自治体の取組みを注視していくほか、実施方法、年齢設定など、それから関係機関との調整も含めて、少し具体的な研究をする時間をいただきたいと考えています。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。最後に、しながわネウボラネットワークに関して、医療との関連についてお伺いします。しながわネウボラネットワークにつながる医療機関、その関係機関とのネットワークは、ネウボラの事業上、非常に大切だと思いますが、医療機関との連携に関しては、今どのように取り組まれているのでしょうか。","respondent":"太田品川保健センター所長","answer":"本年度から、区内３病院の助産師および助産師会の代表、それから産後ケア実施施設の代表などが集まりまして、年２回、保健センター保健師と妊産婦支援のネットワーク会議を、ハイリスク妊婦への支援を中心に行っております。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"意見","question":"私は医師会なのですけれども、一度もお誘いを受けたことがないのですが、なるべく医師会とか、いろいろな職種で顔の見える化を図るように、いろいろご配慮をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"松永委員","kind":"質問・要望","question":"初めに、３０３ページの伝統的産業の振興、７９５万２,０００円について伺います。質問に入ります前に、要望ですけれども、先日の防災フェアに行った際、中小企業センターの１階ロビーでは、伝統工芸実演会が行われておりました。要望です。伺います。３０５ページの若者・助成就業支援事業についてですが、この若者と女性に対して、こうした職人とのマッチングは行われているのか、あわせて伺います。","respondent":"山崎商業・ものづくり課長","answer":"ご質問の後継者の関係につきましては、なかなか一般企業に就労、就職をするような支援と違いまして、いわゆる弟子入りといいますか、やはりそうした就業規則なりでご了解をいただいて導くということよりも、やはりその道を極めるためには、そうしたことよりも。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問・要望","question":"どういう形で支援をしているのか、ぜひお伺いしたいですが、実は、以前、この後継者育成について、我が会派の石田しんご委員から質疑があったと思います。そこで、例えば、家賃補助とか、給料の補助を取り入れてはいかがでしょうか。なかなか難しいとは思いますが、ぜひ品川区でもそうした事業をご検討していただきたいと思うのですが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、それぞれの伝統工芸の方々が取り組まれていることそのものの販路の拡大ですとか、ご商売が柔軟にいくような形で、まずはそういった方面から販路拡大のための展示会のご出展でありますとか、ＰＲの関係。","id":"exchange-069"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ品川区の伝統の技を次世代の人たちにつなげていけるようなシステムづくりに力を入れていっていただきたいと思います。要望です。２７９ページの公衆便所費についてです。その理由について伺いたいということと、もし今後の電気代とか水道代を考えると、公衆便所に関して、全てＬＥＤ化にしたり、節水対策として自動で水が出る手洗い場にしていただきたいと思うのですが、ぜひご意見をお聞かせください。","respondent":"溝口公園課長","answer":"今後も簡易なものについては、維持の一環としてＬＥＤ化を図っていきたいと考えているところです。バルブ等も改修にあわせて省資源のものも採用しながら、環境にやさしい面でも、そういったものを配慮して公衆便所の維持管理に努めていきたいと考えているものです。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"私からは、２７７ページの胃がん内視鏡検診導入準備経費と、３０３ページ、中小企業センター等運営費の２つをお伺いしたいと思います。最初に、３０３ページの中小企業センター等運営費のほうなのですけれども、今年度も品川区といたしましては、中小企業向けの支援メニューということで、さまざま展開をしていく予定かと思います。プレス発表などにも幾つか出ているかと思います。お伺いします。","respondent":"山崎商業・ものづくり課長","answer":"今ご質問の分野につきましては、やはり時代を反映して、そうしたニーズ、要望が多くて、適正に備品の管理費を毎年計画的に執行させていただいて用意をしてきているような状況にはあるかと思ってあります。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問","question":"予算をとりながら適切にということで、本年度、備品の予算でいきますと、貸出用備品等購入の項目になるのでしょうか、４５万円というようなところですが、この辺でどれぐらいの整備がされるのかお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"こちらを周波数の関係ですごく混信するようなことがありまして、今回、ちょうど２月の下旬にそのあたりを改修させていただいて、備え付けの音響アンプのほうにダイレクトに電波が飛ぶようにしまして、そうした意味では、改善されて。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"次に、２７７ページ、胃がん内視鏡検診導入準備経費ですけれども、まず、この胃がん内視鏡の検診につきましての準備を始めるということで、自治体で胃がん内視鏡検診を実施するようになったことにつきましての背景、目的、初めにお伺いしたいと思います。","respondent":"川島健康課長","answer":"背景といたしましては、平成２８年２月に国の指針が一部改正されまして、自治体が実施するべき対策型検診としまして、今までのバリウムによる胃がんの検診に加えまして、胃の内視鏡検査が新規に追加されたという状況です。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"国からの指針が理由ということかと思いますけれども、まずバリウムがこれまで主に実施をされてきたわけですが、この内視鏡検診の医学的なところで言うところのメリット、バリウムと比べてどういうものがあるのかというところをお伺いしたいと思います。","respondent":"川島健康課長","answer":"胃の内視鏡の導入の一番のメリットといいますか、長所になりますけれども、こちらは発見率が高くなるということで、胃がんがより見つかるであろうという、そういう期待があります。","id":"exchange-074"},{"speaker":"塚本委員","kind":"意見","question":"発見率が高くなる、胃がんが日本人にとって最も多いがんですので、この発見率が高くなるという意味では、大変に期待のされる検診なのかと思うのですけれども、先ほどご答弁で、平成３０年度からの導入を考えているというところでございましたが、平成３０年度の実施に向けて、まず対象者はどういう人たちが対象となるのかというところと、それからあと、費用負担の考え方です。","respondent":"川島健康課長","answer":"費用ですが、これはこれからさまざまな検討を加えていく必要があるとは思うのですが、今現在、医療のほうで３割負担で受けますと、本人の負担額が大体５,０００円から１万５,０００円ぐらいというふうに言われてあります。","id":"exchange-075"},{"speaker":"塚本委員","kind":"意見","question":"大体の人数があったのですが、これは例えばバリウムはバリウムで実施をしていくわけだと思うのですけれども、バリウムとの関係です、どちらか選択制になるのか、両方受けるということはあまりないのかと思うのですけれども、バリウムで心配になったから、では、胃の内視鏡とかということもあるのかどうかというところと、それから、費用負担において、今。","respondent":"川島健康課長","answer":"費用負担、先ほど保険を使って本人負担がそのくらいという話をしましたが、それを見て適正な本人負担を幾らにするかということをこれから検討させていただければと考えています。","id":"exchange-076"},{"speaker":"塚本委員","kind":"意見","question":"基本的にはバリウムから内視鏡に移行していくという区の目的だということですので、費用負担等もそういった検診の目的等を反映した形での検討をお願いしたいかと思いますが、今、１０％というところで言うと、４,２００人ぐらいの対象ということでしたけれども、この方々がすべて検診を受けていくというようなことを実施しようとしたときに、医療機関側の受入体制はどのような状況になっているのか。","respondent":"川島健康課長","answer":"今、委員からご指摘いただきました体制が一番大きな問題というところで、現在、胃がんリスク検診をやっているのですけれども、そちらで精密検査ということで回される場合が約６０件程度ということでして、今後、関係機関とさまざま調整してまいりたいと考えています。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"これは品川区の中で非常にあちこちでもちつきをやられていて楽しんでいるのですけれども、今回、ノロウィルス関係なのでしょうか、指導がいろいろなところに入って、残念ながらやめているところもあれば、しっかりきっちりと指導に沿って開催をしたというところがあります。昨年の第２回定例会に質問をいたしました。Ｗｉ－Ｆｉの活用を提唱いたしましたが、その後、動きはありますでしょうか。","respondent":"井浦生活衛生課長、太田品川保健センター所長","answer":"そのような中で、保健所としましては、もちつきでの食中毒を防ぐためのチラシを用意いたしまして、啓発に努めまして、おかげさまで品川区につきましては、無事に地域におきましても、学校施設におきましても。発達障害の方の診断時の対応ですが、まず、保健センターでは診断は行いません。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"それについてはまた１つお答えをお願いします。Ｗｉ－Ｆｉの件ですが、例えば、戸越銀座商店街には、Ｗｉ－Ｆｉもつながっているのです。その中では、商店街の方々との意識を少し高めるような形をして、勉強会等々から始めるのがいいのかもしれませんが、こういうことができますということを話し合う場であったり、勉強会とかというものをぜひつくっていただきたいと思いますが、いかがでしょうか。","respondent":"井浦生活衛生課長、太田品川保健センター所長、山崎商業・ものづくり課長","answer":"もちつきにつきましては、引き続きまして、季節のよき伝統行事ですので、大切にする方向で安全確保のための啓発に努めてまいります。保健センターというところは、健診でスクリーニングを行っているというところでございまして、そこでこちらで気づいた気になるお子さんにつきましては。商店街のＷｉ－Ｆｉなどを含めた多言語対応、ひいては商店街のオリ・パラなどを契機にした来街者の増をいかに商店街の魅力につなげ。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、やはり認識はなかなか難しいと思うのです。いろいろな機関を準備されていても、なかなかそこに行こうとしないという部分があるので、ここは大切なのだということは啓発をかなりしていただきたいと。お子さんが療育もせずにというところになると、せっかくの成長の機会を失ってしまうことになりますので、そこはタイミングをはかって、縦横のつながりをしっかりつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"渡部委員","kind":"確認","question":"このビジネス・カタリストのところもそうなのですけれども、確認なのですが、これはいわゆる情報通信業、ＩＴ企業等に関して対象業種の拡大ということで、この拡大を図るということで、このカタリストに限らず、さまざまな部門でそういう考えでよろしかったですか。","respondent":"立木産業活性化担当課長","answer":"今回の対象業種の拡大に関しましては、４つの事業を考えておりまして、ビジネス・カタリスト活用、国内・海外展示会出展費助成、知的財産権取得支援、それから海外市場調査経費助成、こちらは従来から製造業、それから情報通信業が対象になっておりましたものを。","id":"exchange-081"},{"speaker":"渡部委員","kind":"質問・要望","question":"１６５回とか、事務事業概要に出ていた数だったと思うのですけれども、これは基本的にはいきなりビジネス・カタリストになるのではなくて、当然、中小企業診断士の方等との相談において、あなたは活用したほうがいいですねというような形になるのかと思うのですが、実際のところ、活用に至るまでの経緯を僕が知らなかったので教えていただきたいのと、逆に。","respondent":"立木産業活性化担当課長","answer":"商工相談員ですけれども、そちらのほうと相談内容につきまして事前に内容の確認をさせていただいた上で、適切なスキルを持ったカタリストを派遣するというような形をとらせていただいております。","id":"exchange-082"},{"speaker":"渡部委員","kind":"質問","question":"すみません、今なぜこのようなことを聞いたかと申しますと、２番目に相談内容の多いものが、融資あっ旋について、融資についてとなっていたものですから、融資だと件数的にはいろいろなものを見るとすごく多い中で、あえてここでカタリストが入ることによって融資相談は、そこを入らないと、残念ながら、普通にいったらこの会社は融資ができないというようなところであって、何かを改善することによって。","respondent":"立木産業活性化担当課長","answer":"こちらの事務事業概要で、今、項目として８件２８回というふうに入ってあります融資・補助金活用の部分なのですけれども、主に活用いただいているのは補助金が多くあります。","id":"exchange-083"},{"speaker":"渡部委員","kind":"質問・要望","question":"事業承継士が、士業をお持ちの方がまた別の試験を受けてこの制度を活用されてということで、そういう方々のご支援をいただいて、今回は融資とかもありまして、この辺の制度も聞いていきたいのですけれども、この事業承継に関して、連携する事業で、１００年でしたか、長年やっている企業の表彰式にあわせてセミナーをというような感じなのですが、いわゆるここで言う事業承継、僕が思っていたのは。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、家族間承継、それから従業員承継も含めて、この事業承継支援事業については、区としては、今後取り組んでいくべき事業だということで開始をさせていただいているものです。","id":"exchange-084"},{"speaker":"渡部委員","kind":"質問・要望","question":"これが１世代であれば食べていけるような、しかし、これから先、まだ頑張っていけるような会社であれば、何とかこの制度を使って生き延びてほしいという言い方は変ですけれども、事業を継続していただきたいと、そのために有用な施策になると非常に期待はしています。ですから、それがちょっとの間でうまく継続できるのかと言ったら、なかなか難しい。２,０００万円の融資あっ旋があります。","respondent":"山崎商業・ものづくり課長","answer":"今回、事業承継支援事業が２年目に入りますので、逆に、若い経営者候補の方々に対して、やはり丁寧に会社の経営者としての心構えでありますとか、経営の部分、会計業務などのスキルアップのためにやってまいりたいというふうには思っております。","id":"exchange-085"},{"speaker":"渡部委員","kind":"質問・要望","question":"本当にありがとうあります。当然、区内の金融機関であったり、例えばそれこそ協会、組合とかは、一件一件の状態はわかっているわけです。品川区がこういう制度を始めると言ったときに、しっかりと区もそのようなところと連携を深めていただきたい。それから、少しだけ時間があるので、この中小企業の景況という、１つだけ簡単に答えを教えていただければ結構です。これが何かあれば教えてください。","respondent":"山崎商業・ものづくり課長","answer":"やはり経済の動向に影響を受けるのは、小規模事業者だからこそ影響が大きいのかという側面があります。それゆえ、そうした数字の傾向が出ているのかなというふうには受けとめているところです。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２８９ページの環境三計画改訂等経費に関連して、地球温暖化対策について伺います。昨年１１月に新たな温暖化対策の国際条約「パリ協定」が発効されました。このパリ協定にかかわって、今回の改訂で、地球温暖化、ひいてはＣＯ２削減について、何がどう変わるのか具体的に伺うとともに、なぜ改訂するのか経緯も伺います。","respondent":"三ツ橋環境課長","answer":"そちらを注視していきながら、今回、三計画の改訂にあたりましては、果たしてＣＯ２の総排出量の削減がいいのか、それともエネルギーの使用料についてがいいのか、それとも両方とも勘案していきながら、他区との状況を考えながら、また東京都の状況を考えながら。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、この改訂の経緯については、パリ協定を受けて改訂していくということでよろしいのでしょうか。","respondent":"三ツ橋環境課長","answer":"今回、パリ協定は世界各国が批准しているものです。国がそれに基づいてＣＯ２の排出量などを考えております。地球温暖化防止対策について考えているものです。区といたしましては、国の動向、また東京都の動向も踏まえながら考えているものです。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。この環境計画の中の進捗管理チェックシートには、区全体と、そして家庭部門、公共施設についてはＣＯ２排出量削減目標があるのですけれども、事業者、つまりは業務、産業部門への削減目標はなぜないのか伺います。目標を定める必要があると思いますけれども、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"事業者についての目標ですけれども、事業者は基本的に事業者独自が目標を掲げ、そしてＣＯ２削減については事業者みずからが対応していかなければならない問題です。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"指導しているということですけれども、やはり品川区内でＣＯ２排出量を削減していくためには、事業所についても取組みを行っていく必要があると思いますけれども、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"委員ご指摘の事業者に対してですけれども、基本的には事業者がみずから取り組むべきものと考えております。しかしながら、区といたしましても、支援していく。例えば、助成として支援していくこと、また、環境経営セミナーなどを通じて事業者を支援していくものと考えております。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"届出対象事業者は、１,５００キロリットル以上と言っていてもイメージができないので、どういった広さなのか、従業員が何人ぐらいのところなのかというところもあわせて伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"届出の１,５００キロリットルについてのイメージですけれども、品川区役所も対象となっておりますので、一事業者としては、品川区役所のイメージを持っていただければと考えています。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"イメージでいきますと、品川区役所というのは、本庁舎のことでよろしいのですか。ほかのところの公共施設も含めてということでしょうか。もう少しイメージをわかりやすく伺いたいと思います。そうでなければ、大きな事業者、あるいは中小の事業者、どういうところに働きかけていくことが効果的なのかということも検討できないと思いますので、改めて把握していただきたいと思いますが、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"区全体として地球温暖化防止に向けて取り組まなければいけないものと考えていますので、１,５００キロリットル以上、以下の把握はまた違う観点だと考えています。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりそういった細かな把握をしていくことで、今は区全体でやっていくということでいいかもしれませんが、別々に把握していって、進んでいるところ、進んでいないところ、そこに重点を置いていくということも必要だと思いますので、今から把握していっていただきたいと思います。この施策の抜本的見直しが必要だと思いますけれども、具体的にどうやっていくのか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"こちらにつきましては、サマールックキャンペーンでありますとか、また、ウォームビズキャンペーン、さまざまな取組みをしております。特に、しながわＥＣＯフェスティバルは、区内約３万人を動員できる大きな取組みですので、そちらにつきましても対応してまいります。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"啓発とあわせて、実際に具体的に進めていく助成金ですとか、そういったところを、これまでやってきてもなかなか進まず増えているというところですので、さらに力を入れて支援をしていっていただきたいと思いますし、このＣＯ２排出量の中で、やはり電気のところが大きいというところで、排出係数が増えたり減ったりというところで、なかなかご苦労もあると思うのですけれども。","respondent":"三ツ橋環境課長","answer":"排出量が上がらない電源ベースがどういうものなのか、今すぐにはお答えするのが難しいところですけれども、国といたしましても、大きな目標値、マイナス２６％という大きな目標を掲げております。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"目標達成のためには、まちづくりについても見直しが必要ではないでしょうか。２００７年の一般質問で、大崎駅周辺で６０ｍ以上の超高層ビル２３棟の延べ床面積が約１００万m2で、その再開発によって１０万トンのＣＯ２が単純計算で排出されていると。この点から言えば、再開発推進路線を見直す必要があるのではないでしょうか。伺います。","respondent":"稲田都市開発課長","answer":"再開発におきましても、非常に環境対策は重要というところで、この地域におきましては、まちづくり連絡会が当時ありまして、現在、まち運営協議会というのですけれども、こちらにおきまして、都市再生ビジョンを作成して、その中で平成１７年７月に環境配慮ガイドラインをつくり。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問","question":"そのチェックしているところで、実際にどうなのでしょうか、増えているのか、減っているのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中におきましては、東京都の環境局のほうに書類を提出したり、その中で変更があれば、事業途中でも変更しながら、設備、建築物の熱負荷の低減、それから省エネルギーシステムの採用、そういうところについて評価をやっていくのですけれども。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"高層化を進めていけば、やはり延床面積が増えてしまうので、いくら効率よくしても、ＣＯ２排出量は増えてしまうと思うのです。ですので、やはりそういったところも考えながら、地球規模の問題ですので、排出を抑制していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"木村委員","kind":"意見","question":"２７７ページの健康診査、２７９ページの公衆便所費、それから３０３ページの公衆浴場商業協同組合からです。２７７ページの一番上の２０歳以上の健診が行われていますけれども、私たちの頃には、本当に考えられないようなことでありました。そこで、行政側のお考えが多少変わってきたのだと思いますけれども、２０歳まで繰り上がった理由は何だったのかお聞かせください。","respondent":"川島健康課長","answer":"糖尿病に至っては、症状が出てきたときにはもうかなり進行している場合が多いということで、なるべく早い段階で、糖尿病ですとか、高血圧といった生活習慣病を予防するために、生活習慣が大きく変化する時期が２０歳ということですので。","id":"exchange-098"},{"speaker":"木村委員","kind":"質問・要望","question":"はい、わかりました。確かにそうですね、お酒を飲める年代ですし、そしてたばこを吸う年代ですから、大きく変わるのでしょうけれども、まだそんなには変わらないと思っていたのですけれども、２０歳からということで、健診がそういう若い方たちにももっともっと興味を持ってもらえるようにお願いしたいと思います。","respondent":"川島健康課長","answer":"これはまだ１年通して結果は出ておりませんが、２０代の方の受診数でいきますと、今のところ、６０３件という実績が出てあります。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問","question":"６０３件が多いのか少ないのかということになると、ちょっとあれなのですけれども、次にまいります。品川区民の皆さんは、健康診査に対してどのように考えているのか。特に２０歳からの若者が、健康に対してどのように考えているとお思いでしょうか。","respondent":"川島健康課長","answer":"やはり若年齢の方は、自分の健康を過信したり、それから自分は病気にならないというふうに思っている方が非常に多い世代ではないかということですので、そういったことに対する啓発の意味も込めまして、この健診をやって、自分の体をチェックして。","id":"exchange-100"},{"speaker":"木村委員","kind":"意見","question":"２７９ページの中ほどにありますけれども、公衆便所費、８,３６４万円余からですけれども、公衆便所維持管理に予算の約半分ですけれども、４,０５４万円を充てています。以前、公園のトイレットペーパーの持ち去りの件でも何度か公園課のほうにお話をしたことがありました。その後、持ち去りはどのようになっているのか、また、行政としてどのような処置をとったのか、あればお聞かせください。","respondent":"溝口公園課長","answer":"これにつきましては、毎日清掃する際に、点検または補充をしているものです。そういった中で、常日頃から、持ち去り等がないように維持管理をしていますので、今のところ、新たに持ち去りがあったという形での報告は受けていないということで聞いております。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"品川区には公園が１４４カ所、そして緑地４カ所、計１４８カ所あり、そして公園トイレの数は１０６カ所ということですけれども、うち身障者、だれでもトイレが３３カ所、男女共用トイレが３９カ所設置してあります。それ以外に、公衆トイレ３６カ所、児童遊園トイレが２０カ所、計１６２カ所あります。安全性に関しては、どのようなところに気配りをしているのでしょうか。お聞かせください。","respondent":"溝口公園課長","answer":"安全対策ですが、ほかの委員のときにもお話しさせていただきましたが、さまざま業者による委託、または巡回、そういったもので対応、また、いたずらがひどいところにつきましては、警備会社がすぐ駆けつける体制をとっておりますので。","id":"exchange-102"},{"speaker":"木村委員","kind":"意見","question":"ぜひお願いをしたいと思います。そして、修理代。トイレを壊されたりするのでしょうけれども、この修理代に３３２万円余ですけれども、本当に心ない人たちによってかかる費用は本当にもったいないことであろうと思っていますけれども、どのような被害があって、また、それを防ぐ方法、また先ほどとよく似ていますけれども、お答えください。","respondent":"溝口公園課長","answer":"次に多いのが、便所のドアが壊されたりとか、また、重たくなって動かなくなったり、そういったものに対しての修繕という形で、毎年３００万円ほど予算要求をして修繕を行っているものです。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"３０３ページの下から４行目なのですけれども、区内の銭湯のことなのですけれども、大変厳しい経営状況の中、生き残りをかけて、いろいろなイベントや銭湯の楽しさ、爽快さを何とか伝えようと頑張っていますけれども、銭湯自体が行政側にどのように映っているのかわかりませんけれども、ずばりお聞きいたしますが、銭湯はあったほうがいいのか、それともなくなってもいいかなとお考えでしょうか。","respondent":"川島健康課長","answer":"まちの銭湯は、大事にしていかなければならない、なくなっては困るというふうに考えてあります。","id":"exchange-104"},{"speaker":"渡辺委員","kind":"質問","question":"３０５ページ、しながわ観光大使関連事業、３１１ページ、商店街ステップ・アップ支援事業全体のところで伺います。それと、商店街のステップ・アップの特に後継者育成だとか、地域交流も全部含めているのですが、特に後継者育成、この中で現状のねらいと課題が、当然文字どおりという中で、どんなねらいで、どんな効果、助成をやっていくのか教えてください。","respondent":"鈴木文化観光課長、山崎商業・ものづくり課長","answer":"観光大使関連事業ですが、１つは、観光大使でありますシナモンの着ぐるみとか、それから関連グッズの配布等を含めて、品川のイメージとシナモンのイメージをセットで広く知っていただいてＰＲするという事業の目的になります。そういう意味では、後継者の育成が急務になっているというようなことに対応して、後継者の育成をしていく事業ということで、今回、ステップ・アップ支援事業の中に組み込みまして、区としましても。","id":"exchange-105"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、後継者育成のところを中心に伺いました。まさしくこれは今に始まったことではなく、ずっと課題であり続け、いろいろな策をやっている中で、すぐ成果は出ないかもしれませんが、わりと私が聞いている限り、きっかけを求めていたり、あるいは、当事者でなくても、周りの方が、あの息子さんや娘さんが継いでくれればなという、そういう二世で優秀な方がいる。それは１つだとします。そういう方もいる。","respondent":"鈴木文化観光課長、山崎商業・ものづくり課長","answer":"今、ご提案のありました観光大使を次の展開として数多くの方にお願いするというご提案ですが、それに関しまして、実は現段階でシナモロールの活用ということで、区のほうで予定をして検討している仕組みがございまして。そういう意味では、今回、商連が実施する予定ですけれども、そのエリアを熟知した、例えばエリアマネジャーとご商売に造詣のある方々などが組みまして、そのお店に直接こちらから出向く出前講座などを第二段階のご支援として。","id":"exchange-106"},{"speaker":"渡辺委員","kind":"質問","question":"商業のほうですが、出前講座的なものが、商業だけではなく、時代的にどうしても必要なのかなという感覚を持っています。この在勤というところをまたクローズアップして、そうすると、よくおいしいところも知っているとか、ランチだろうと、夜だろうと、やはりこういう方々もすごくリストアップしたらおもしろいのかなと思うので、いかがでしょうか。この辺の挙げさせていただいたもの。そこまでまず伺います。","respondent":"鈴木文化観光課長","answer":"全てご指摘のように、品川の魅力発信、観光を広めていく上で、大使という名前を使うかどうかは別としまして、サポーターなり、発信の一員ということで、ご協力いただけると思いますので、幸いにも、今お話に出たような団体等は。","id":"exchange-107"},{"speaker":"渡辺委員","kind":"質問","question":"時間の中で、観光という中で、まちかど観光案内所を１点伺います。情報を自分も聞かれるから知っておく。そういう中で、現状どの程度の場所、それとあと、大まかに去年の増刷とか追加の状況、順調やに聞いていますが、力を入れるべきものという点から、現状どんな感じか、あるいは、今後、柔軟に補充も含めて成り立っていくのだろうと思うので、その点、最後にお知らせください。","respondent":"鈴木文化観光課長","answer":"まちかど観光案内所ですが、現時点、平成２９年度末までの予定を含めまして４９カ所、事業者・店舗等の方にご協力をいただいて、区の観光に関するＰＲなどを協力いただいているものです。","id":"exchange-108"},{"speaker":"こんの委員","kind":"質問","question":"蔓延防止対策としては、手洗い、うがい、また咳のエチケットということで励行していることもあると思いますし、啓発としてホームページやポスター、チラシ、こうしたことで周知を図っているというふうにありますけれども、要するに、こうした蔓延対策、防止対策というのは、効果が果たして本当に出ているのか、大事なことではあるのですけれども、そこら辺はどう捉えていらっしゃいますでしょうか。","respondent":"舟木保健予防課長","answer":"流行の開始の時期等に結構左右されるのではないかと考えています。手洗い、うがい、咳エチケットによる流行防止なのですが、それはそれなりの効果はあると考えています。それについては引き続き予防啓発をしていきたいと考えています。","id":"exchange-109"},{"speaker":"こんの委員","kind":"質問・要望","question":"私は、昨年の予算特別委員会でもこの点を取り上げ、平成２５年のときにもインフルエンザ予防接種についても取り上げさせていただきましたけれども、この予防接種の必要性をいま一度確認をさせていただきたいと思います。接種をしている方を区としては把握されていらっしゃるのでしょうか。接種率を区として把握をし、また、どのように接種をしている状況を捉えていらっしゃいますでしょうか。","respondent":"舟木保健予防課長","answer":"それ以外の年齢、小児を含む方についての接種者数等については把握はしておりません。接種している方、していない方で罹患率に差があるかということについても、これは定期の方を含めてもこちらのほうでは把握はしていないような状況です。","id":"exchange-110"},{"speaker":"こんの委員","kind":"質問・要望","question":"これはやはり何か具体的にもっと対策をとらなければいけないというふうに私は考えるのですけれども、そうなると、やはり予防接種しかないというふうに思います。そこら辺のところは、いま一度お考えいただきたいと思いますし、このままでいいというふうに考えていらっしゃるのか、その点、もう一度お願いします。","respondent":"舟木保健予防課長","answer":"現在、子どものインフルエンザの予防接種については、ただいま国の定期接種化の検討対象のワクチンの中には入ってはおりませんので、国の検討の状況等を見ながら研究させていただければと考えています。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"意見","question":"１つ目は、産業経済費全般について、２つ目は、３１５ページ、品川ビジネスクラブ助成金について。先に、産業経済費全般についてお尋ねいたします。こうした観点から、産業振興関連予算、そして観光関連予算、それぞれ特徴や今後の施策の方向性、中心になる重要なポイントについてお尋ねいたします。","respondent":"山崎商業・ものづくり課長","answer":"商店街の支援の関係ですが、やはりオリンピック・パラリンピックなどを視野に、商店街の方が国際化推進対応事業ということで、来日外国人の方などへの工夫したおもてなしの取組みを発掘・ＰＲをしてまいる新規事業などを通じて、商店街の魅力向上と、そのＰＲ。","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"桜新道商盛会などは、大田区と協力して夢フェアなども開催しております。明日の土木費の関連になりますけれども、特に立会川周辺はまちづくりビジョンを策定すると伺っています。産業経済費ということですので、商店街の国際化対応、今お話が少しありましたが、それから、にぎわいづくりなど商店街活性化の観点で、どのようにこちらの所管でかかわっていくのかということをお尋ねいたします。","respondent":"山崎商業・ものづくり課長","answer":"まちづくりの話がありましたけれども、周辺は倉庫街が大規模マンションに変わるような土地利用も進行しているようなところもあって、区としましては、その一画の魅力をさらに上げるようなことをハード系のまちづくりの分野と、私ども商店街のにぎわいを維持しつつ。","id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"地域の方々のご意見を伺ったりという形でいろいろ活動されています。全体の話はここまでで、次に、品川ビジネスクラブの助成金についてお尋ねいたします。平成２８年度第４回定例会でも質問をいたしましたが、品川産業支援交流施設（ＳＨＩＰ）の指定管理者である品川ビジネスクラブですけれども、この助成金４,７２３万円余は、財団運営費の補助金であると考えます。","respondent":"立木産業活性化担当課長","answer":"品川ビジネスクラブの会員数ですが、今年度４月の段階で１４８の会員数となります。これは法人・個人合わせてになります。大体約７割程度が区内の会員の方ということで聞いてあります。","id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから一方、区内企業の割合が７０％という中で、事業費も今お話を伺った４００万円超でしょうか、区の助成金でほとんどの運営が行われているということで、地元の経営者の方々にいろいろとお伺いしますと、この会員制のビジネスクラブが展開されている事業は、なかなか区内中小企業向けにはとっつきにくいというか、思えないと、そのような事業が多いと。","respondent":"立木産業活性化担当課長","answer":"ビジネスクラブの独自の事業に関しましては、区との連携の中で、例えば個別集中的なところをビジネスクラブが、ベーシックな部分を区がやるというような役割分担の中でやっている中で、来年度、より緊密な形で連携をとっていく予定です。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問","question":"団塊の世代の方々が後期高齢者になる、７５歳になる時期が、統計上、日本では過去最高の高齢社会になるわけです。それから医療費の増大を抑制していくということを長期的な目標として掲げていくべきと思うのですが、いかがでしょうかということが１点。それからあと、障害者歯科健診も同じように高齢になっていくわけでありますから、そこの高齢化対応についてはいかがでしょうかという質問をまずします。","respondent":"川島健康課長","answer":"障害者歯科健診、実績が平成２６年から平成２８年まで、７件、１１件、１２件と数は少ないものではありますが、非常に重要な事業であると、こういった方たちにも健診の機会を提供するのは重要であるというふうに認識していますので、ただ。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"これから高齢化社会になっていくことは間違いないわけで、さまざまな議論がある中で、やはり疾病が増えていくわけですね。それから、観光プランのほうですけれども、初めに、「わ！しながわ」で表現するような、あるいは魅力を一言であらわすような、そういう言葉を募集すると言ったらいいのですか、そういうようなことを企画してみてはいかがでしょうかという提案なのですが、いかがですか。","respondent":"中島企画部副参事、鈴木文化観光課長","answer":"しながわ」の後に魅力を続けてほしいという思いで展開をしています。今後、具体的な展開についても考えてまいりたいと考えています。しながわ」のロゴを合わせたデザインも完成しておりますので、ご指摘のように、連携しながら、しっかりと品川の魅力を発信していきたいというふうに考えております。","id":"exchange-117"},{"speaker":"伊藤委員","kind":"提案","question":"そうしたら、さらに思うのですけれども、「わ！しながわ」の後の言葉を、それこそ募集したらいかがですか。「わ！残念ながらあまりよくなかった。悪いとは言わないのだけれども、ぜひご理解していただきたいのは、あるところは、相手は竹下景子さんです。それに対して品川区はどうなのだという思いがあるので、ぜひ次のステップとして企画をしてみてはいかがでしょうか。提案ですが、答弁をお願いいたします。","respondent":"中島企画部副参事","answer":"いろいろご意見を承っておりますが、引き続き、活用してまいりたいと思います。竹下景子さんのような著名な方を使うアイデアもありますが、今年度、区制７０周年のプロモーション動画も考えておりますので、インパクトのある内容についても検討してまいりたいと考えています。","id":"exchange-118"},{"speaker":"伊藤委員","kind":"提案","question":"だから、坂井市の三国では、竹下景子さんという著名な方をプロデュースしてやっているわけではないですか。だから、品川区でも、やるのだったら、それぐらいのことをやったらどうですかという提案なのです。そうしないと、せっかくシティプロモーションをこれから展開していって、全国に向かって品川区を売り出していくときに、いいのかという思いがありますので、もう一言答弁をお願いいたします。","respondent":"中島企画部副参事","answer":"なかなか打ち出し方というのは、今でもいろいろ考えております。やはり新しさと懐かしさがあるということは、品川区の魅力だと考えていますので、各所管も含めまして、品川区の魅力を全国に発信できるように、今後も積極的に努めてまいりたいと思います。","id":"exchange-119"},{"speaker":"伊藤委員","kind":"意見","question":"すみません、今、パッと品川区の出身の有名人が出てこないのですけれども、探せばいろいろいらっしゃいますね。その人がいいかどうかは別の問題として、要は、そういう著名人を据えて、予算をかけて企画もしっかりつくって品川区のプロモーションビデオをつくってくださいというお願いでありますので、このことについては、ぜひもう１回正確な答弁をお願いいたします。","respondent":"中島企画部副参事","answer":"前向きな答弁をしてまいりたいと思いますが、現段階では、映像をこれからつくってまいります。今、委員ご提案ございましたところも含めまして、品川区の顔が見える形の動画も検討してまいりたいと考えています。","id":"exchange-120"},{"speaker":"伊藤委員","kind":"提案","question":"だから、先ほどの提案もあったように、ぜひこちらのサンリオのシナモンのホームページの中で、例えばシナモンが観光大使に就任しましたということのＰＲ、それからあと、品川区の子どもたちからシナモン大使へのコメントを書き入れてもらうとか、それから、誕生日もありました、３月６日なのだそうです。午前中にありましたけれども、そういうことについての方向性をお知らせください。","respondent":"鈴木文化観光課長","answer":"誕生日のイベント等、今後の連携については、ご指摘のとおり、せっかくなっていただいたものですから、効果的な活用をできればというふうに考えております。","id":"exchange-121"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから３１５ページの事業承継支援事業についてお伺いしたいと思います。そこで質問です。区役所で受理する場合も、すぐに面談をすることができるのかどうかもお伺いしたいと思います。オリンピックのホッケー会場からも近い中で、品川区としては、都立公園ではありますが、どう対処するのか、都に求めるのかどうかということも含めて、何らかのアクションは必要だと思うのですが、いかがお考えでしょうか。","respondent":"太田品川保健センター所長、井浦生活衛生課長、山崎商業・ものづくり課長","answer":"面談率につきましては、１月末の妊娠届出が３,５２４件ですので、それに対して２,６５０件の面談を行っておりまして、７５％ということになります。一義的には公園の管理者による管理責任というところがあろうかと思いますが、区としても実態を把握いたしまして。待ち時間の解消なのですが、今、乳幼児人口が増えておりまして、今年はかなり待ってもらうことも多かったと思いますが、来年度以降は。これは今年度から事業を始めたばかりということで、現在は予算上のそれぞれの企業の方々のニーズに応えて。","id":"exchange-122"},{"speaker":"あべ委員","kind":"提案","question":"そうではなくて、当面の措置としては、保健センターを届出場所として、かつ、ここで面談もして、お土産もありますというようなことまで書いた上で、でも、ここに行けない方は区役所でも受けて、後日、保健センターで改めて面談がありますみたいな話の展開をするだけでも、少しは違うのかなというふうにも思いますが、区としては、この面談率向上ということ、それから、面談場所ということで。","respondent":"太田品川保健センター所長、山崎商業・ものづくり課長","answer":"もう少しわかりやすく保健センターを一番上に出す等については、今後検討してまいりたいと思います。面談率を上げるのは、やはり妊娠届出と同時に面談をするということが一番ということは、よく理解しております。事業承継士は、もともと背景に中小企業診断士の資格を持っていらっしゃったり、公認会計士などが、一定の事業承継に係るカリキュラムを受けた方が承継士として登録されて、それが委託契約をしている事業承継センターから派遣される。","id":"exchange-123"},{"speaker":"あべ委員","kind":"質問・要望","question":"要望だけ。この週末、羽田空港で、品川、大田、八丈島の観光のイベントがありました。いろいろな形でエリアで観光として打っていくというのは非常に有効なことだと思います。全国から品川だけを目指すというのは、ちょっとやはり観光のスタイルとしては特殊かなと思います。特に八丈島を含む島しょ部との連携も、品川区のエリアでしたら、ぜひいろいろと進めていっていただければなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"南委員","kind":"確認","question":"２８９ページの航空機騒音調査に関連してお尋ねしたいと思います。航空機騒音調査、これは初めての予算計上ではないかと思うのですけれども、航空機の騒音に特化した測定なのかどうか、そこを確認したいと思います。","respondent":"三ツ橋環境課長","answer":"航空機騒音調査のご質問です。こちらは予算としては、昨年度も予算計上しておりまして、予算は今年度が初めてではございません。","id":"exchange-125"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。そのところの認識を改めたいと思います。さて、低空飛行の危険性について質問をしたいと思います。世界各地の空港で、大勢の人が住んでいる市街地上空を低空で通過して着陸する、こういう状況の空港はあるのでしょうか。あるとしたら、どこか教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"低空という部分が何フィートを低空と言うのか非常に難しいところですが、資料によりますと、例えばニューヨークでありますとか、ロンドンのヒースロー空港、そのあたりが資料の中では出されているものだと考えています。","id":"exchange-126"},{"speaker":"南委員","kind":"質問・要望","question":"品川の上空を低空する２００ｍから３００ｍ、そういう関係で質問しているので、そういう状況で答えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"国からの資料によりますと、ほかの例えばロンドンのヒースロー空港の周り、またニューヨークのラ・ガーディア空港の周りの部分につきましては、１,０００フィート程度、また１,５００フィート程度という資料はあります。","id":"exchange-127"},{"speaker":"南委員","kind":"質問・要望","question":"そのほかの問題についてもありますけれども、トップの３項目については、ずっとこの議会でも議員の中でも住民の中でも共通して出されている点なので、ここについて取り上げて紹介したわけですけれども、とりわけ落下物については、区は、落下物対策として徹底した整備点検を国に対して強く求めるというふうな、そういう姿勢をずっと一貫して表明してきておりますけれども、具体的にどのような場面で。","respondent":"中村都市計画課長","answer":"国に対しましては、区といたしましては、例えば説明会が品川区内で行われるですとか、あるいは、さまざま先ほど申し上げました安全基準の情報提供ですとか、こういったもので国と話をする機会があります。そういった機会を捉えて、国のほうへは対応を求めているところです。","id":"exchange-128"},{"speaker":"南委員","kind":"質問・要望","question":"点検とか整備とかを徹底する、いろいろな体制をとって到着した航空機をきちんと国土交通省の役人がチェックをするという、そういうことも含めた体制をとっていくという話は繰り返されているわけですけれども、本当にそういうことで落下物１つとってみても、この危険、心配を払拭させることができるのか、その点について区はどう考えているのでしょうか。","respondent":"中村都市計画課長","answer":"安全基準の内容につきましては、航空機の整備ですとか、あるいはパイロットの教育、そういったものについて基準を設けて実施しています。ただ、整備が具体的にどういった内容かというところになりますと、これはかなり専門的な分野に入り込むところだろうです。","id":"exchange-129"},{"speaker":"南委員","kind":"質問","question":"そういう部品がもし残っているとしたら、それはそれで推測できるかもしれません。なくすようにするにはどうしたらいいのかということを伺っておきたいと思います。いつ、どこで、誰が設置した会議体なのか、その目的は何か、何回開催されているか、また品川区との関係はどういうふうになっているのか、関係があるとしたら、品川区ではどなたが参加をしておられるのか、それについて伺います。","respondent":"中村都市計画課長、藤田都市環境部長","answer":"落下物についてですけれども、これは飛行前の点検チェック、それから飛行後にも落下物、脱落部品などがないか、こういったものを国としては徹底して検査をしていく。幹事会ということで、部長級の会議があるということと、あと、作業部会、ワーキンググループということで課長級の会議があるというような形になってあります。","id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"副区長が参加対象だと、こういうことですね。これは、今、開催されていないということですけれども、なぜ開催していないのか。いいということでうなずいておられたから。そして、全然開かれていないとなると、議会で出された意見、住民の皆さんが寄せてくださったご意見、要望、こういうものについてどこの場面に反映しているのですか。反映できているルートがほかにあるのでしょうか。伺います。","respondent":"中村都市計画課長","answer":"区民の皆様の意見につきましては、これはこういった東京都が主催する会議ではなくて、区として直接国へ伝えているものです。","id":"exchange-131"},{"speaker":"南委員","kind":"質問","question":"品川区は、こういう会議、国の協議会に反映することが必要だという認識は多分持っておられるから、先ほど答弁されたような国へ直接伝えているというふうなことになっているわけですけれども、つくられている機関、正当なルート、そういうものを使ってきちんと届けるという、そういう意識はないのですか。ないとしたら、なぜしなかったのか、そこを伺います。","respondent":"中村都市計画課長","answer":"国に対する要望あるいは要請につきましては、これは連絡会やワーキンググループの中では情報共有の場ということで、都として国に対して意見を上げる際の情報共有の場だというふうに認識をしております。","id":"exchange-132"},{"speaker":"南委員","kind":"確認","question":"私はそういう姿勢ではあまりにもまずいのではないかと思います。去年の７月２８日にこの協議会が開かれました。別ルートであるからいいということではなくて、私はこの協議会と連絡会の関係について、区はどんなふうに認識しているのか、必要ないと思っているのか、改めてそこを確認したいと思います。","respondent":"中村都市計画課長","answer":"そういったときには区としての考え方をしっかりと東京都へ伝えることも必要ですし、また、区民の皆様の声を直接国に届けるということも大事だと考えておりますので、さまざまなルートを使って国に対して伝えていっているところです。","id":"exchange-133"},{"speaker":"若林委員","kind":"質問・要望","question":"最初に、共通商品券普及促進事業についてお聞きいたします。そこで質問ですが、来年度、平成２９年度予算の予算額について、平成２８年度より多い理由をお聞かせいただきたいと思います。それから、消費喚起効果について、平成２８年度、今年度の効果はどうであったのかお知らせください。予算が組まれた平成２９年度の見込みは、どのように捉えられているかお聞かせいただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"消費喚起につきましては、平成２８年の春ですけれども、やはり３億円の１割ということですので、消費喚起効果のパーセンテージは落ちておりまして、２７.２８％というようなことで、６億６,０００万円に掛け合わせますと。","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"当然、売り出す側の商店のほうが一生懸命されていると思うのですけれども、どのような工夫をされているのか教えていただきたいと思います。２回アンケートをとられて、分析をされていくという答弁が繰り返されておりますので、このデータや分析が商店街にフィードバックをされて、みずからが分析をして傾向や対策、創意工夫をされているのか、ここら辺についてもお聞かせいただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"繰り返しになりますけれども、今回の調査につきましては、通常の販売方式による通常の３億円の１割というようなパターンの時期のアンケートでございまして、今回、また春にアンケートなりをしっかり数字をとるのは、予約販売方式になってどうなのだろうというようなことも含めて。","id":"exchange-135"},{"speaker":"若林委員","kind":"確認","question":"時間がなくなりましたので、その後のコメントはまた後ほどということで、そ族昆虫については、１点だけ。今回、先ほどありましたけれども、１万４,０００カ所が増えて、これが私道の部分だということで、この私道の部分、私道で１万４,０００カ所、全体で私道としては何カ所あるのか、この１万４,０００カ所の選定方法はどうするのか、これを確認させてください。","respondent":"井浦生活衛生課長","answer":"私道につきましては、道路現況調査によりまして、道路延長約１０万ｍということで把握してございまして、何ｍごとに雨水マスという国の基準がありますので、そこから１万４,０００カ所という数字を算定したものです。","id":"exchange-136"},{"speaker":"若林委員","kind":"質問","question":"最後に、所有者によっては、うちは結構ですとかということもあるので、そこら辺のきめ細かなオーナーとの対応はいかがでしょうか。","respondent":"井浦生活衛生課長","answer":"きめ細かく適切に対応してまいります。","id":"exchange-137"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"中継所なのですけれども、これはオリンピックが決まったときに、返還が平成３２年だけれども、使えるように交渉をしていこうという話になっていたと思うのですが、その後の経緯が、我々もどうなったのかというのを、それを追っていなかった私も悪いのかもしれないのですが、そこは今どういう形になっているのかということを、まず初めに教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"ただし、する中では、２０年の縛りというのはなかなか外せないというようなお声をずっと聞いているところで、どういった使い方ができるかということをずっとやらせていただいたです。","id":"exchange-138"},{"speaker":"石田（秀）委員","kind":"意見","question":"私はここは諦めないで言っていってほしいと思っています。平成３０年度中というと大変だけれども、平成３１年に更地にして誘致をしてくるという１つの種地として考え方を持っていくというのは、あそこは運河もあるし、それこそそういう意味では不定期航路も使えるわけだし、そういう話を私はその中の候補の１つにするべきだと思っているのですが、そこら辺のお考えをお聞かせください。","respondent":"柏原企画調整課長","answer":"そういった中で、他区では、一定程度、清掃の業務に支障を来さないような工夫をしながら、別の用途であったり、我々品川区でも、そういったいろいろな広い捉え方ということも考えながら、有効活用をさらに研究していきたいというふうには思ってあります。","id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"備蓄倉庫もあるし、それはしようがない、それしか使えないと言うから、あそこを今、そういう形で利用しているわけで、そこは粘り強くやっていただいて、１つの誘致をしようということであれば、そういうところの種地として、１つの候補として、それはやっていくというぐらいの話をしても、今、東京都でオリンピックをやろうとしているわけですから、東京都にもそういう話を、私はあそこの立地だったら。","respondent":"小林品川区清掃事務所長","answer":"したがいまして、現状では、車の誘導路等も含めて、活用は困難というふうにお話は伺っていますけれども、その活用の仕方については、ちょうど隣接する資源化センター等も手狭で施設計画が立ちづらいところになっておりますので。","id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひその部分はよろしくお願いしたいと思います。それから、公衆便所は確認だけさせていただきたいと思っています。その体制整備は、必ずつくっていきますということだったと思うのだけれども、そこら辺の体制整備は必ずできているものだと思っているのだけれども、そこら辺のところを教えていただきたいと思います。","respondent":"溝口公園課長","answer":"災害時の公衆便所、公園トイレの利用についてのご質問です。基本的には、マンホールトイレ等あるものについては、地域の方たちが囲いをつくっていただいたり、トイレを設置していただいて使うような形になっているものです。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"意見","question":"すみません、私の理解が悪かったのかもしれないのですが、それは私のイメージだと、１回やめたはずなのです。","respondent":"溝口公園課長","answer":"今、災害時のトイレの利用です。基本的には地域の方たちにトイレを利用していただくような形で今考えているものです。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはもしあれだったら、各町会長とかに再度確認をしていただいて、鉄の棒になるのかどうか、そういうことも含めて、しっかり配っていくということを再度やっていただきたいと思います。私のわかっている範囲では、その意識は今はもうなくなっているかなという感じがあるので、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"私は、３０５ページ、都市型観光プラン推進事業についてお聞きしたいと思います。特に人口減少に直面する地域が経済的な自立を保つため、地域外から訪れる観光客からの収入をてこにして地域内の経済環境を高めることが地域内居住者の収入と雇用の維持、創出につながっていると考えられているというような報告がありますが、観光を推進する品川区はどのような考えをお持ちなのでしょうか。","respondent":"鈴木文化観光課長","answer":"品川区の観光ですが、昨年、平成２７年度末に策定をしました都市型観光プランに基づいて、区の魅力発信、それから区の観光資源を多くの方に楽しんでいただきながら、住んでいる品川区民の区への愛着もあわせて感じていただくというところが目的です。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"今、お聞かせ願いましたけれども、歴史的な資源、あと豊富な水辺環境など、多くの魅力があることを発信するとありますが、全国にある歴史的な文化遺産や大自然の美しい地形とは、この品川区内のものは比べ物にならないほど、やはりレベルは落ちているわけです。全国に誇れるようなきれいな水辺環境もありません。それでも観光を前面に出すのですか。教えてください。","respondent":"鈴木文化観光課長","answer":"そういう意味で、区民の方が愛着を持っていただける、また、日頃楽しめる、それから区外から訪れた方も楽しんでいただけるというのが品川区の都市型観光だと考えております。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"はっきり言って。通じないでしょう。観光と言ったら、皆さん、全世界の人はどう思いますか。観光地があるのだな、きれいな景観があるのだな、いろいろな我々が見たことのないものを品川区で見られるのだな、そういうふうに思うのが観光ではないですか。別の呼び方にしたほうがまだいいのではないですか。観光というのは、違いますか。","respondent":"鈴木文化観光課長","answer":"委員のご指摘のような観光は従来からある観光として認識をしております。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"全然この品川区、一生懸命やっているのはわかります。でも、全然それ、世界に発信する、日本全国に発信する、本当にそんなものが、そのぐらいのものでなぜできるのですか。全国に、世界に。観光資源がある、これ、誇れますか。もうちょっと簡単に言いますけれども、水辺環境、あれがきれいな水ですか。東京湾です。皆さん、一般の人はそう思うのではないですか。もう一度ご見解をお聞かせください。","respondent":"鈴木文化観光課長","answer":"よいまちだというふうに考えていただけると考えております。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問・要望","question":"物価も安い。だって、それをやらなくても、人はどんどんあふれてくる、住宅は増えてくる、では、何なのですかという話です。あえてシティプロモーション、それから観光推進事業をしなくても、人がこの品川区を求めて引っ越してくるのです。多くの人が。それに対して観光という名前をつけて、皆さん、来てください、見てくださいというのは、どうなのかなと思うのですが、もう一度ご見解をお聞かせください。","respondent":"鈴木文化観光課長","answer":"それら全てをあらわすときの切り口、テーマとして、シティプロモーションであったり、観光があるということありますので、観光のためにやるのではなくて、品川区のよさを知る手法の１つとして観光があるというふうに考えていただければと思います。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"今、人に知らせるという話がありました。だって、十分知っているから皆さん来るのではないですか。そうでしょう。小さいお子さんから高齢者まで、立派な事業をやっています。これだけのことをやって、ここで観光、では、見に来ました、ああ、これがまちなのだ、品川区なのだ、そのギャップは相当出てしまうのではないですか。やはり「観光」という名前は、何か違和感を思うのですが、それでも違いますか。","respondent":"鈴木文化観光課長","answer":"観光のイメージもさまざま捉える方によって違うかと思いますけれども、区で今考えております観光の周知も、１つは、区民の方への周知です。その区民の方でも、身近にそういう楽しめるものがあるというのを、意外と区内の全部を知っていない方もいらっしゃいます。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"観光消費額が約１兆円もありますが、ですが、観光の活況が市税収入の増加につながっていないのです。京都市。でも、よそでつくったものを買っても、それは市の収支としては、その分、よそから仕入れているのですから、サービスしている、売っている分しか収入は上がらないのです。ですから、今、文化観光課長は言っていましたけれども、私はこういういろいろな面を見たときに、やはり何がいいのだ。","respondent":"鈴木文化観光課長","answer":"委員ご指摘のように、品川の魅力、また、よいものを知っていただくという思いは同じです。ただ、私の場合は、その伝える手法のテーマが観光ということで区から任されておりますので、観光一本でしっかりとやりたいと考えております。","id":"exchange-150"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから、最初、企画調整課に私は言いたかった。こういうふうにうたってどんどん出しています。片や文化観光課は、言われた事業をきちんと推進してやらなければいけない。お仕事です。私は、これは企画調整課も、また財政課もしっかりその辺を見て、これから品川区のためにやっていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"改めて、品川区が求める観光というのはどういうことなのか、私が考えるには、ある一定の方たちが都市に来て、ほかを見に行った後に、例えば品川区に寄って、またちょっと違うものを見たりとか、海外では見られないものを、いわゆる生活感を感じてもらうとか、そういったことが品川区にとっての観光なのかなと思いますので、改めて観光について、文化観光課長の思いを教えていただければと思います。","respondent":"安藤文化スポーツ振興部長","answer":"私のほうからお答えします。品川区については、都市型観光プラン、昨年の末にできました。それをご覧いただければ全てわかると思いますが、観光地を目指しているわけではないのです。都市型観光を目指しているということです。","id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、２７７ページの成人歯科健診と、３０５ページのシルバー人材センター支援事業について伺いたいと思います。成人歯科健診ですけれども、前回、決算時に伺ったときは、まだ検討中だということで、対象年齢拡大ということまでしかわかっていませんでした。この５歳刻みになった根拠を伺いたいのと、あと、この通知対象です。健診内容です。それと、健診１件に対しての区の負担を教えてください。","respondent":"川島健康課長","answer":"１つ、５歳刻みの考え方ということですが、こちらは毎年成人歯科健診を受けていただくということも、それはいいのかもしれませんけれども、私どもの自治体の健診につきましては、これを受けていただいて。","id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"確認","question":"それはやはり年々歯の状況は変わっていくと思うのです。なのに、なぜ歯は５歳刻みなのか、その違いを伺いたいと思います。それとあと、通知対象、全ての人というのは、そうすると、２０歳の人全てに通知をされるということ、会社の健康保険、社会保険などに入っている人などは対象外ではなく、全ての２０歳の方が対象ということで確認させてください。そこも確認させてください。","respondent":"川島健康課長","answer":"受診券につきましては、２０歳から７０歳まで５歳刻みで、社会保険の方がどういう状況かというのは把握できないので、区民の方で全ての対象年齢の方にお送りするような形になります。レントゲンは、健診の内容には入ってございません。","id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"全ての対象年齢の方に通知が送られるというのは、よかったと思います。そういったことを考えれば、体の健診、２０歳からの健診と一緒に健診ができるようにしていくべきではないかと。ですので、やはり５歳刻み、５年刻みの根拠は私はないと思うのです。ですので、１年ごとでやっていただきたいというふうに思います。そこを改めて求めたいのです。そこはいかがでしょうか。","respondent":"川島健康課長","answer":"そういったところもありますので、まずこの施策の体系の中でやっていく。異常があったら、それは当然、歯医者を受診するしかないというふうに思いますので、５年に１回は定期的に健診を受ける機会を提供して、それがまた歯科受診のきっかけになればというふうに考えてあります。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１件の健診の区の負担も、合わせると大体９,０００円ちょっとなのですか。そういったところでも、十分可能だと私は思いますので、毎年実施を求めていきたいと思います。そして、毎年実施を強く要望したいと思います。次にいきたいと思います。シルバー人材センターの支援事業ですけれども、平成２８年の会員数と受託事業件数、それから事業収入を教えてください。","respondent":"立木産業活性化担当課長","answer":"シルバー人材センターの平成２８年度１月末の会員数ですが、２,４５８人、受託事業件数が１万５,０６５件、それに伴う事業収入が１０億５,７００万円となっています。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問","question":"受託事業の件数は、結構減っていってはいるものの、これだけあるのだなということで、会員数も徐々に減ってきてしまっているとは思うのですけれども、こうした高齢者の方がまた働くというところの背景について伺いたいのです。そういった声が今寄せられているのです。区はこの状況をどう考えているのか。そして、今シルバー人材で働く方々の実情などは把握されているのでしょうか。","respondent":"立木産業活性化担当課長","answer":"そうは申しましても、最近、多様化する中で、高齢者の方が何かしらの収入の上乗せというような希望を持たれているという会員の方も中には存在するということも確かですので、そういった中でシルバー人材センターでは、第４次の中期計画の中では。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問","question":"まだまだ働かなければいけないという、こんな老後になると思わなかったということだったのです。そういうことでシルバー人材センターで働かれているのです。そして、その方は企業から仕事を引き受けて、企業まで行って働いているのですけれども、この分配金が時給換算すると最低賃金以下、９００円も切るという状況だそうです。そして、交通費も出ない。こういったことに区はどうお考えでしょうか。","respondent":"立木産業活性化担当課長","answer":"安い労働力として高齢者の会員を見ているということではなく、やはりそれなりの生きがい、それから経験を生かした社会参加というところでご参加いただいているものと考えています。","id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ区として、最低賃金になるように支援していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"不妊治療助成は、先般、本会議でも質問させていただきましたが、改めて確認と要望をさせていただきたいのですが、まず、現在の一般不妊治療助成ですが、これの助成金の金額だとか、仕組みについて教えていただくのと、また、本会議で取り上げさせていただきましたけれども、平成２９年度の予算で、東京都で助成が出ることになっておりますが、その概要についてお知らせください。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"一般不妊治療の助成だということなのですが、上限が５万円であるということ、それから妻の年齢が３４歳以下などというふうに新聞にはあったのですが、都に確認したところ。予算書です、３１１ページの下から５行目にあります商店街国際化推進事業、１,１７０万円のうち、プレス発表させていただいた商店街おもてなし店ＰＲ事業につきましては、９７０万円というようなことです。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"提案","question":"１０年ぐらい前に、平成２０年のときに要望した際には、検討するみたいになっていたのですけれども、その後、こちらとしてもあまり追いかけなかったのですが、この間も言ったとおり、私もそういうことを気にするような体になりましたものですから、塩分とか一々コンビニで見ていると、細かく載っているのですけれども、なかなかそれを見ながら買ったりとか、また、食事も外に食べに行くと。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"ただ、区での実施につきましては、やはり委員もおっしゃっておりましたが、ハードルが高いのかなというふうに思っておりますが、幾つかの先行自治体の取組み、今もご紹介いただきました部分を確認するほか。それから２つ目につきましては、既に、例えば外国の方々がよく言われる多言語化の対応をされていたり、これは売っている物品に対して指さしの確認をするようなボードをつくられたりとかというような、身近な取組みから。","id":"exchange-161"},{"speaker":"たけうち委員","kind":"質問","question":"不妊治療については、さまざまお話がありましたので、ぜひ前向きにお願いします。最後の商店街ですけれども、本当に大事な事業になってくると思うのですけれども、ただ、一応ここに出ている関連事業で、地域活動課とか、子ども育成課があるのですけれども、観光の視点もかなりあると思うのですけれども、文化観光課とはこれから連携していくのだと思うのですけれども、そこだけ教えてください。","respondent":"山崎商業・ものづくり課長","answer":"もちろん私ども商店街としましても、従来どおりきっちり連携して、魅力ある品川のエリアということで、強力に発信なり取組みをしてまいりたいというふうに考えているところです。","id":"exchange-162"},{"speaker":"鈴木（真）委員","kind":"質問","question":"清掃費で２９９ページになりますが、廃棄物対策費、その辺で質問したいと思います。ですから、品川区の中で今、環境アセスメントの対象になっているのはどのぐらいの数があるのかということを教えてください。ですから、作業員の方は非常にご苦労なさっているというふうに話も聞いているのですが、その辺の問題の解決に向けて、区の当局としてはどのように考えているか、そこら辺を教えてください。","respondent":"三ツ橋環境課長、小林品川区清掃事務所長","answer":"環境アセスメントについてのご質問です。今現在のところ、４カ所から出ております。目黒清掃工場であったり、川崎天然ガス、また、委員ご指摘の今の４号線の部分、そして京急立体化となっております。来年度以降、できるだけ早期に、この資源ステーションの位置づけ等も含めて、円滑な回収ができるように、保管場所、集積所の整備とあわせまして、それに応じた車両の配置も含めて検討してまいりたいと考えております。","id":"exchange-163"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、うまく収集し、また事故のないように気をつけていただくように、よろしくお願いしたいと思います。アセスメントの関係です。もとへ戻ると、ホッケー場の関係が絡んでくるのではないかと思うのですけれども、あそこがホッケー場ができると、やはり樹木が大分影響を受けるのではないかと、その辺では区のほうに話は来ているのでしょうか。","respondent":"三ツ橋環境課長","answer":"したがいまして、委員ご指摘のように、大井ホッケー会場、また、潮風公園、こちらはＩＯＣの要請により、全ての会場においてアセスメントをするようにという要請がありますので、対応といたしましては、この両方の会場がアセスメントの対象となっております。","id":"exchange-164"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。緑という意味で、品川区のみどり率が現在どのぐらいになっているのかというのと、今後の目標的にはどうなっているのか教えてください。それから、清掃関係の回収です。最近、私も見に行っていて、きれいになってはいるのですけれども、そういう出されたごみの管理、区なのか、警察に話をしてもという、その辺の区と警察の協力体制みたいな関係を教えてください。","respondent":"三ツ橋環境課長、溝口公園課長、小林品川区清掃事務所長","answer":"アセスメントの区長意見ですけれども、自主アセスメントではありますが、きちんと区長意見としては申し述べることができますので、緑地に関しても。続きまして、目標ですが、平成２４年に水とみどりの基本計画を策定しておりまして、その中で、策定後１０年、平成３３年までに目標を定めておりまして。最終的には、１月９日の警察との協議で、以後、危険を伴う住環境の悪化に対しては、警察としても、あわせて指導していくという形で連携して対応した結果。","id":"exchange-165"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"みどり率ですけれども、これからもその目標へ向かってしっかりやっていっていただきたいと思います。回収のほうです。さっきも言っていましたが、今はクリアしていました。地域の方も大変に喜んでいまして、区と清掃関係、道路の関係、警察とタイアップしてきれいにできたということなので、これからもこういう案件が万が一あったら、ぜひ対応をよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/697202?Template=document&Id=1062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":124140,"voices":395}},{"id":"h29-20170314-3","meetingId":"h29-c-budget","date":"2017年3月14日","dateIso":"2017-03-14","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を161件抜き出しています。","topics":[{"id":"topic-01","title":"起立少数であります。ご着席願います。 よって、本動議は否決いたしました。 それでは、改めまして、第５号議案、平成２９年度品川区一般会計予算","agenda":"起立少数であります。ご着席願います。 よって、本動議は否決いたしました。 それでは、改めまして、第５号議案、平成２９年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"おはようあります。３２３ページ、街路樹等維持管理費、３５５ページ、改修工事助成、３５３ページ、住宅耐震化支援費、３５７ページ、空き家改修についてお伺いをさせていただきたいと思います。初めに、街路樹剪定のことをお聞かせを願いたいと思います。この街路樹等維持管理費、剪定等ありますけれども、それと、かむろ坂の桜植替え工事費について、内容をお知らせいただきたいと思います。","respondent":"多並道路課長","answer":"ただ、その１段上のかむろ坂の桜につきましては、その中でも、かむろ坂の桜が非常に長年あるということで、今回、今年度に調査した結果、不健全木があったということで、それを計画的に植え替えていこうということで、来年度、さくらまつりが終わった後に。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"桜というのはおおよそどのぐらいが寿命なのか、教えていただきたいのと。桜の時期になると、桜を楽しみにしておられる方が当然いらっしゃいます。そういった方のご意見で、桜があまりにも伐採され過ぎて、剪定され過ぎて、桜の見ごろのときの桜が、すごく見栄えがよくなくなってしまって、そういう基準というのがどうなっているのか教えていただきたいと思います。","respondent":"多並道路課長","answer":"桜の寿命等ですけれども、一般的に高木の寿命、全体的には８０年ぐらいと言われております。ただ、桜については、もう少しそれよりは短い時期だろうということで、一般的には言われているところです。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３５５ページ、改修工事助成、および３５３ページ、住宅耐震化支援費についてお伺いいたします。それと、住宅耐震化支援費なのですけれども、これも新しい事業で、プレス発表で、住宅耐震緊急促進アクションプログラムに基づく耐震化促進ということですけれども、予算書を見ますと、おそらくこれは耐震化支援費に入ると思うのですけれども、それを確認させていただきたいと思います。","respondent":"鈴木建築課長","answer":"プレスの資料の中で赤く塗っているところが、重点地区としてやっていきたいというところで、この赤いところが、東京都が平成２５年に調査をかけた中で、倒壊危険度が高いエリア、そこで重点的にやっていきたいというものです。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"このがけの改修のことなのですけれども、いろいろ調査をして、耐震、がけ・擁壁安全化アドバイザーの派遣によって、これからどこになるか、どこになるかと言うか、依頼があったときにこういう助成をするということで、特にがけなのですけれども、こののり面に関して、のり面のことは、当然、事業者が見て構造計算をしてやっていくと思うのですけれども、実際にこの工事が入ったときに、所管の課として。","respondent":"鈴木建築課長","answer":"がけの改修、実際に始まった場合は、まずは基本的な事項として、所有者の方にアドバイザーを派遣して、１回１時間から２時間程度、金額ですとか、課題ですとか、そういったお話をさせていただいて、工事の際に、２ｍ以上を超える擁壁になりますので。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３５７ページ、空き家対策についてお伺いをさせていただきたいと思います。空き家改修２件、防草シート購入１０件ということなのですけれども、これもおそらく、これぐらいの程度のことがあるだろうという予測の上の件数だと思うのですけれども、これも改めて、そういうことなのかどうなのか、お聞きしたいと思います。お知らせください。","respondent":"今井住宅課長","answer":"防草シートの購入のほうですが、現在、空き家のほう、草木の管理、特に雑草の、こちらのほうの苦情を多くいただいておりますので、保全通知を差し上げている方の中から１０件程度はご希望があるというふうに考えておりまして、こちらも１年目ですので、目標ではありますけれども。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"この防草シートということで、草が生い茂っているところ、近隣の方からの苦情があるということで、防草シートを購入ということなのですけれども、実際に施工というか、防草シートを敷く工事というのは、区のほうで依頼を受けて、区のほうで、この当該空き家のところに防草のシートを敷くという認識でよろしいのでしょうか。","respondent":"今井住宅課長","answer":"今般の防草シートの購入支援につきましては、防草シートの代金の２分の１程度になります限度額５,０００円で助成をするという形で考えております。シート代のみです。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"意見","question":"ぜひ、そういった地域の、近隣の方からの依頼がありましたら、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"３１７ページ、駅周辺等放置自転車対策事業、３２３ページ、かむろ坂桜植替え工事費、３４３ページ、公園整備事業費について伺っていきたいと思います。駅周辺等ですが、区内のバイク、それから二輪の保有台数について、今日はわかりますでしょうか。","respondent":"桑波田交通安全担当課長","answer":"バイクの保有台数ですけれども、こちら、税務課のほうにちょっと確認いたしまして、原付につきましては１万４,７７６台、自動二輪につきましては８,１２２台が登録されているということで、確認いたしました。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"確認させていただきました。そうすると、２万台ぐらいが、大体推移かと思うのですが。そのバイクの課金が、１件当たり大体９,０００円ぐらいで計算すると、１０年間で８億４,７００万円ぐらいの課金になるということなのです。ちょっと不勉強で教えていただきたいのですが、こうした課金のものというのは、歳入として、何らかの形で品川区まで入ってくるものかどうか、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"委員長。では、結構です。これは確認します。要は、肝としては、このバイクの駐輪場が非常に少ないという、ユーザーまた販売業者の方からお声がある中で、そうした課金でされたものとかを整備費用に使うことができるのかという、そういう概略的な部分でした。原付しか止められない所と、自動二輪も止められる所の、その内訳がわかれば教えてください。","respondent":"桑波田交通安全担当課長","answer":"バイクの駐車場所のスペースについては先ほどのとおりなのですけれども、一応、施設の大きさによって、大きいバイク用の所もありますし、原付用のちょっと狭いスペースという所もありますので、ちょっと細かいところの数字、内訳までは把握していないところです。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"これは、その使っている方のモラルの部分もあるとは思うのですが、やはり、そうしたせっかく整備されていて、当然、原付しか止められない、大型も止められるという、その駐輪場の状況もあると思うのですけれども、こうしたバイクの駐輪場の利用誘導について、もう少し工夫をして、放置自転車もさることながら、放置バイクもしっかりと。","respondent":"桑波田交通安全担当課長","answer":"バイクの駐輪につきましては、バイクの都内の駐輪マップというものも作成されておりまして、こういったものを各駐輪場のほうで、これは都内全域になるのですけれども、こういう所に所在するということで、そういったマップのお配りだとか、あとホームページ等でも。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"なかなか、自転車と、車と、バイクと、それからベビーカーとか、車いすとか、いろいろその辺のせめぎ合いもあるかとは思うのですが、そうした整備もしっかりと今後進めていただきたいと思います。かむろ坂の桜植替え工事費ですが、まず冒頭、これは毎回お聞きしていますが、桜の本数ですね。街路樹約４,０００本に対して、今現在、何本になったか教えてください。パーセンテージも教えてください。","respondent":"多並道路課長","answer":"区内の街路樹については、現在３,９９９本、委員のご指摘のとおり、約４,０００本です。そのうち、桜が１,３１８本で、割合としましては、約３３％が桜で、ほかの区よりは非常に多い街路樹の割合だと、我々、認識しています。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"他区と比べると多い。具体的な、かむろ坂の所でありますが、先ほど若干質疑がありましたが、不健全木が１９本あって、中が空洞状態のものがあると思うのですが、それだけなのか、もしくは全部なのかというところも含めて、植替えの時期、それから工法、昨年の決算でも要望させていただいた根上がり対策ですね。この辺も含めてやるのか。歩道整備、それから１,５００万円の予算内訳。これを教えてください。","respondent":"多並道路課長","answer":"かむろ坂の桜についてですが、全部で１２１本ございまして、全部をまず外観調査をし、それで、最終的には詳細調査というのを行いまして、今、委員のご指摘のとおり、空洞が５０％以上あるものが１９本あったということで、今回はその空洞、いわゆる不健全木。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"詳細ありがとうございました。あそこ、今現在、桜のトンネルになっているのですね。１９本ですから、全部ではないので、多分、植え替えた所は、どうしても少し空が見える。これは聞きません、提案だけです。もう１つ、桜という視点で、毎回申し上げておりますが、品川区内にある駅ですね。桜の木が植えられていくように、これも引き続き、要望も含めて、提案も含めて、言い続けていきたいなと思います。","respondent":"溝口公園課長","answer":"おもてなしトイレにつきましては、一応、事業としては、平成３２年、オリンピックの開催までに、ある程度重点的に、旧東海道などの観光名所、または大井町駅等の主要ターミナル、またはオリンピック会場の周辺。","id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"平成２７年度の決算のときに、利用者へのおもてなしとか、また、観光、オリンピック・パラリンピックの視点、使いたくなるトイレ、気持ちよく使えるトイレで、おもてなしトイレの工夫をということで、提案をさせていただいていたので、個人的に、この今回の観光拠点のおもてなしトイレという具体的な名称も含めて、非常に喜んでおります。ましてや、武蔵小山、大きい駅ですから。","respondent":"溝口公園課長","answer":"４カ所から６カ所ぐらい、そのぐらいが大体、公園のほかの改修工事等もありますので、そういったものを合わせますと、やはりこのぐらいが、ちょうど計画的に進められる限界なのかなというふうに感じているものです。","id":"exchange-015"},{"speaker":"つる委員","kind":"提案","question":"時間の関係で、また改めて各やっていきたいと思いますが、人員の関係であれば、その辺も、また拡充を可としてされるようなことも、提案もしていきたいと思いますし、財源であれば、いろいろなところから引っ張ってきて、促進されるようにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"３５７ページ、マンション管理支援、また、３４７ページ、大崎駅周辺地区再開発事業、大崎西口駅前地区について伺います。わかればですが、区内の居住世帯のうち、分譲マンション住まいの方は、どれぐらい占めるのでしょうか。わかれば教えてください。大体でもいいです。それと、マンション建替え時の課題は何だと区は考えていらっしゃるのかも伺いたいと思います。","respondent":"今井住宅課長","answer":"最後に建替えの実績等ですが、私ども、マンション建替え法が変わってから、建替えの実績というものは、住宅課で把握しているものはございません。ただ、今１件、建替えを行いたいというふうな具体的なご相談があります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"共同住宅ということでざっくりと、しかも国の調査ということですので、ぜひ、区として、区内のマンションの実態を、数としてつかんでいただきたいというふうに思います。それで、この直面しているマンションというのは、区内にどれぐらいあるのか、区は把握してらっしゃるのか伺いたいと思います。実態調査が必要だと思うのですけれども、この実施も求めますけれども、いかがでしょうか。","respondent":"今井住宅課長","answer":"ただし、私ども、実際にマンション管理セミナーということで実施いたしましたけれども、そちらの学識経験者の知見によりますと、旧耐震・新耐震だけではなくて、建築基準法が変わった１９７１年あたりですとか、一定の年数が過ぎても、十分。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"最終的には長寿命化もあれなのですけれども、これだけ多くのマンションができていて、超高層のほうも増えているわけですけれども、最終的には必ず、いわゆる終末期問題と言うのですかね、建て替えるということに直面しなくてはいけないと思うのですね。超高層マンションのほうが、こうした建替えや更新が困難であるとの認識は、区にはあるでしょうか。この先行モデル事業の成果とは何だったのか、伺います。","respondent":"今井住宅課長、稲田都市開発課長","answer":"いずれにいたしましても、まずは人数の、組合の入居者の皆さんの合意が必要になりますので、高層・超高層にかかわらず、住民の方が今後、何十年後か、３０年後、５０年後以降の建替えに際して、どういうふうに考えていくかというのを。マンション再生制度、まちづくりと連携したマンション再生制度の構築に向けた先行モデル事業ということで、大崎駅西口駅前地区が先行モデルとして選定されまして、平成２７年度、平成２８年度と。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"合意が必要だとおっしゃいまして、そのとおりだと思うのですが、先ほど紹介したように、合意自体が、超高層マンションのほうが大変なのではないかということをおっしゃったので、そこに関して、超高層マンションのほうが困難があるのではないかということについて、もう一度、区の認識を伺いたいと思います。事務局はどちらが担っているのか。それと、計画はどのような計画なのか、わかれば教えてください。","respondent":"今井住宅課長、稲田都市開発課長","answer":"こちらは戸数の問題ではなくて、いかに計画的に皆さんで合意形成をするかというふうに考えておりますので、超高層・高層というふうな考え方で区別するものではないというふうに考えております。地権者数、土地所有者、マンションの分譲の方も入れて、約２２０人ほどです。借地権者が１名おられます。この地区で、借家人等はちょっと今のところ把握できないのですが、建物数から言えば、このエリアの中で１３棟あるところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"提案","question":"地区の中でも駅から離れた端の土地との交換なども提案されたそうです。商売の自由さえ奪われるのは、納得いかないと。この方の土地は、耐震化したばかりのビルですから、この終末期の問題も既にクリアしているわけなのですけれども、納得いかないと。この場所で事業を続けたいという希望は当然のことだと思いますけれども、品川区はそういうふうに思わないのでしょうか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"この大崎駅の西口地区、この地区に関しましても、平成２４年から地元の方と意見交換会等しておりまして、今後また合意形成等に向けて進めていくと思われます。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"私からは、３２５ページの補助１６３号線整備について、３２７ページのオリンピック・パラリンピック施設周辺無電柱化事業について、３４１ページのしながわ水族館運営について、関連して、３４３ページのしながわ区民公園改修工事、また、戻りまして、３１９ページのシェアサイクル事業について、３２３ページの自転車推奨ルート整備について、伺いたいと思います。","respondent":"多並道路課長","answer":"この事業につきましては、現在、大井町線のガードの拡幅工事を東急に委託して行っておりまして、これが平成３１年度までかかる予定です。その後に、下の街路の整備を行うのが１年間、平成３２年度ということで、現在、平成３２年度に完了させる予定で、工事を進めているものです。","id":"exchange-022"},{"speaker":"松永委員","kind":"提案","question":"この補助１６３号線の整備によって、ちょっとセットバックされるのかという感じになるのかなとは思うのですけれども、そこでちょっと提案なのですけれども、区役所前でよく、先ほども言いましたが、タクシーの乗降者が多いことから、区役所の入り口付近、また区役所内に、タクシーの乗降者スペースをぜひつくっていただきたいと思うのですけれども、そのことについて伺います。","respondent":"多並道路課長","answer":"方向サインの件ですけれども、バス停の前に、ちょうど今、東急電鉄が耐震工事を行って、ちょうど我々の補助１６３号線でやっている工事から続いて、耐震工事をやっている範囲がありますので、そこの部分かと思うのですけれども、そこも、東急電鉄のほうに。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"平成３０年度には、補助２６号線も開通される予定となっておりますので、このことも踏まえながら、事業を進めていただければと思います。もし、そうして取り壊されるのであれば、新しい壁画を、また同じ学校の生徒さんに描いていただきたいとは思うのですけれども、そのことについてどのように考えていらっしゃるのでしょうか。それとも、また残していくのか、その辺、お伺いしたいと思います。","respondent":"多並道路課長","answer":"補助１６３号線は新たな事業区間ということで、この区役所を下りた坂下の大崎支線のガードの所かと思いますけれども、ちょうど今、これからＪＲ東日本と設計について協議しながら、事業を、どのような整備を進めるかという協議を進めていくところです。","id":"exchange-024"},{"speaker":"松永委員","kind":"提案","question":"ぜひよろしくお願いいたします。次に、３２７ページのオリンピック・パラリンピック施設周辺無電柱化事業について伺います。この道路詳細設計等委託４,２８０万円についてでありますが、どこの道路を指しているのか伺います。合わせて、以前質問させていただいた、大井ふ頭中央海浜公園付近の路上駐車対策についても伺いたいと思います。","respondent":"多並道路課長","answer":"ただ、今回の道路整備に当たっては、今ちょうど、東京都、大田区とも続くので大田区、警視庁とも協議しているところですけれども、自転車レーンを整備する予定となっています。","id":"exchange-025"},{"speaker":"松永委員","kind":"提案","question":"今後、東京モノレールとの協議をして決めていかれると思うのですが、ぜひ、大井競馬場駅から直接、勝島橋につなぐ道をつくっていただきたいのですが、これは提案ですけれども、ぜひよろしくお願いいたします。次に、３２３ページの自転車推奨ルート整備について伺います。東京２０２０大会に向け、東京都では、自転車シェアリングのステーション位置などから選定されるとも伺っております。","respondent":"多並道路課長、安井土木管理課長","answer":"２０２０東京大会に向けまして、東京都のほうが、自転車推奨ルートというのを、平成２７年４月に発表しておりまして、この中で、品川区も、その中で、国道・都道・区道ということで連携して、面的に整備していくのですけれども。観光の部門とも十分協議しながら、最もアクセスポイントとしてふさわしいような場所を今後検討していくということで、これから検討していくという形になってあります。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"パーキングメーターがあるエリアについては、気になっていたので、ちょっとお伺いしました。ご検討よろしくお願いいたします。次に、３４１ページのしながわ水族館運営費について、関連して３４３ページのしながわ区民公園改修工事について伺います。気になっていたのですが、以前、何かあったのでしょうか。そのことについて伺います。","respondent":"溝口公園課長","answer":"委員お話しの所は、レストラン横の階段になっている部分だと思います。整備した当初から、あそこは階段状になっておりまして、水に触れ合える、勝島の海に触れ合える、そういったゾーンの設定をして、階段状になっているものです。","id":"exchange-027"},{"speaker":"松永委員","kind":"提案","question":"今では、難しいかもしれませんけれども、勝島の海ということで、ぜひその海を活用してみてはいかがかということで、ちょっと提案させていただきたいと思います。以前ちょっと聞いた話によると、昔あの場所でボートをやられていたということをお伺いしたのですけれども、なぜボートを取りやめてしまったのか、その辺も伺いたいと思います。","respondent":"溝口公園課長","answer":"しながわ区民公園の中の唯一の水辺、また、水に親しめる、また水族館もある、そういったシチュエーションの中での整備をしている、また、そういうコンセプトのもとにつくってきて、皆さんに親しまれてきている公園だというふうに認識しています。","id":"exchange-028"},{"speaker":"松永委員","kind":"意見","question":"今、初めて知りました。そういう事情があるというのであれば、ちょっとスワンボートというのは難しいかなと思うのですけれども、ぜひ釣りのスポット、よろしくお願いしたいと思います。こうした来場者の視点に立って、ぜひ水族館以外にも、そうしたアトラクションを１つ増やしてみてはいかがかと思うのですが、最後に改めて区の意見をお聞かせください。","respondent":"溝口公園課長","answer":"勝島の南側ゾーンの改修工事も、来年、詳細設計に入っていく予定になっておりますので、そういったところを含めまして、総合的に、皆さんに親しんでいただける施設、公園になるように、検討していきたいというふうに考えているものです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、３３５ページ、水辺利活用事業、水辺空間整備促進、３３９ページ、水辺景観ビューポイント抽出、３３７ページ、水辺の賑わい創出構想検討委託、３４２ページ、公園新設改良費についてお伺いをいたします。区長も施政方針で、品川区の目黒川、天王洲などの魅力ある水辺資源がある、これを大きく花開かせ、多くの方に見て実感していただきたいと感じていますとおっしゃられていました。","respondent":"和田河川下水道課長","answer":"水辺の舟運の今後の展望ということですけれども、現在、舟運社会実験継続中でございまして、その社会実験の内容を見て、今後検討していくわけですが、１つの構想としましては、東品川二丁目防災桟橋というものが今年度中に完成いたしますので、そこに定期航路を誘致して。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"どのくらいの来訪者人数というのは、まだ予想はできないですか。","respondent":"和田河川下水道課長","answer":"これをベースに、今後どのようなルート開発、どのような乗降客数ですかね、そのようなものが考えられるかということを、検討していきたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"そこで、水辺景観ビューポイント抽出や水辺の賑わい構想検討委託という、この２つの事業があると思われるのですけれども、この２つの事業は一体どういうものなのかをお知らせください。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"品川区内の景観に対する配慮といたしまして、今、建築物の見え方に対して、建築主の方に配慮していただいているところですけれども、今度、水辺のほうにも着目をいたしまして、水辺から見える市街地の景観、こういったものについて。京浜運河のみならず、目黒川、それから天王洲、勝島運河、いろいろな水辺が品川区にあるわけなのですけれども、これらの水辺を、それぞれの状況なり、環境なり、それから文化なり、この辺を生かして。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど、東品川二丁目防災桟橋をハブとして活用していくということで、非常に頼もしいお答えをいただきましたけれども、このハブとなる東品川二丁目防災桟橋を活用して、これを１つのきっかけとして、天王洲エリアのかつての輝きを取り戻すべく、天王洲エリアの地域全体の発展・活性化にぜひともつなげていっていただきたいと考えておりますけれども、区のお考えはどのようになっているでしょうか。","respondent":"和田河川下水道課長","answer":"対岸には、我々の品川天王洲桟橋もあります。現在、ここを天王洲の協議会のほうで、イベント等で使っていただいているところなのですけれども、今後は、東品川二丁目防災桟橋も含めまして、天王洲全体で水辺の活性化ということでご利用いただければというふうに考えてあります。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも、これを１つのきっかけとして、あと、そうした民間の活力、飲食店、商業施設などの積極的な誘致などを行っていただいて、また、すばらしい天王洲エリア、地域全体の活性化、発展につなげていっていただきたいと考えております。次は、公園についてお伺いいたしますけれども、しながわ中央公園拡張部に、前回、建設委員会で視察に参りました。","respondent":"溝口公園課長","answer":"今後も、そういった広域避難場所、または木密整備推進課と連携しながら進めておりますが、防災広場、そういったところの整備については、しっかり防災の視点も取り入れた公園整備というのを行っていきたいというふうに考えているものです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも整備を進めていっていただきたいと考えております。災害時にはコンロにもなる防災スツール、かまどベンチというのも、これは非常に有効だと考えておりますけれども、これは同様に、今後の公園や改良時に進めていくべきだと私は考えているのですけれども、品川区としてはどのようにお考えでしょうか。","respondent":"溝口公園課長","answer":"ほかの公園につきましても、地域から、かまどベンチの設置のお話が、公園改修に合わせて地域の方たちの意見を聞く中であれば、そういったものはしっかりと整備をしていきたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"地域の方から、いざとなったらコンロとなる防災スツール、かまどベンチは、非常にいいので、ぜひ進めていってほしいというお声も頂戴しております。防災広場なのですけれども、全体的に品川区の西側が多いイメージで、東側が少し少ないと、私は感じるのですけれども、地域バランス的に防災広場を品川区東部のほうにも設置していっていただきたいなと考えているのですけれども、その点いかがお考えでしょうか。","respondent":"溝口公園課長","answer":"今現在、防災広場の整備につきましては、木造密集地域の解消ということを目的に整備を進めているところです。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"よくわかりました。東側は、木造密集地域が少ないので、やらないということでよろしいのでしょうか。","respondent":"溝口公園課長","answer":"これまでも、これからも、しっかりとそういったご意見を聞きながら整備を進めていきたいというふうに考えているものです。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"公園は、普段は遊び場、いざというときは対災害用設備ということで、首都直下型地震もいつ起こるかわからない、もう来るのではないかと言われていることから、一定の改修時期を待たずに、できるところから早目に小まめに整備を進めていくべきだと考えているのですけれども、また、この災害用設備を活用した訓練もやっていただきたいのですけれども、その点、区としてのお考えはいかがでしょうか。","respondent":"溝口公園課長","answer":"災害時のかまどベンチとかを含めまして、災害時に使える施設の整備です。これはやはり災害時に、私ども行政側がつくっただけでおしまいというわけではありませんので、その先、地域の方たちがどのように使っていくのか、そういったところも１つ大切だと考えています。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。そして、ちょっと時間がありますので、３４１ページの八潮地区まちづくり検討経費について、お伺いをしたいと思います。若い人がちょっと少ないというお声を聞きますので、これは、まちづくり検討に当たって、交通アクセスの向上や、人を寄せ集める、そうした商業施設誘致などの仕掛けが必要だと考えていますけれども、その点、区としてはいかがお考えでしょうか。","respondent":"中村都市計画課長","answer":"この八潮のまちづくりについてですが、今、委員ご指摘の交通アクセスの件ですとか、あるいは賑わいですとか、こういったものも課題の１つとしては捉えておりますけれども、ただ今、この八潮地区、入居開始してから約３４年ということで、建物そのものは、まだ当分。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３３１ページ、下水道管改修事業、３３５ページ、河川管理費、３４５ページ、荏原南公園子ども達のアイデアを活かした公園についてをお伺いいたします。１点目に、下水道管改修事業、河川管理費についてお伺いいたします。平成２８年１１月７日から、小山五丁目、六丁目、荏原五丁目の工事がスタートしておりますが、スケジュールを確認させていただきたいと思います。","respondent":"和田河川下水道課長","answer":"下水道局に確認しましたところ、ご指摘の西小山駅の南側の工事につきましては、当初、平成２９年１１月完了予定で工事を進めていたところなのですけれども、この工事の前に、管きょ内の調査を行ったところ、想定外の多くのひび割れ等が確認されたため、この工事は。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"今、平成３０年５月中旬まで工事の延長ということで、最新の情報をいただきました。こちら、地域への事前の説明の徹底と、立会川幹線の再構築を着実に進めていただくことを都に要望していただきたいと考えております。私も、今後さらに勉強するつもりでおりますが、報告義務の有無にかかわらず、区側もアンテナを張っていただいて、区民の安心・安全への取組みを強く要望いたします。","respondent":"和田河川下水道課長","answer":"今後も、この工事、水を流しながらやる工事ですので、少々時間がかかる工事ですけれども、着実に推進していくよう、働きかけてまいりたいと思います。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"働きかけのほう、ぜひよろしくお願いをいたします。ちょっと専門用語も多いもので、詳しく、わかりやすく教えていただきたい部分があります。経済的耐用年数８０年程度で再構築という言葉があるのですけれども、こちらと、あと、モルタルの強度について。ＳＰＲ工法の部分。工事工法の概要について、わかりやすく、簡単で構いませんので、お願いします。","respondent":"和田河川下水道課長","answer":"今、おっしゃられたのは、耐用年数８０年、基本的には、下水道管は耐用年数が８０年程度で考えているですので、８０年サイクルで更新をしていかざるを得ないというようなことを記述されたものです。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"次の質問、２点目なのですけれども、荏原南公園、子ども達のアイデアを活かした公園について、お伺いいたします。引き続き、地元町会のご意見をいただき、調整しながら進めていただきたいと考えますが、現時点の詳細設計について、平成２８年度、どのように進めてこられたのか、公園の全体像を教えてください。特に、以下の８つのポイントについて、詳細設計の内容を確認させてください。","respondent":"溝口公園課長","answer":"安全部会のほうでは、様々な工事パトロール、またはヒヤリハット、そういったものを共有する中で、工事の安全・安心に努めているところです。今後も引き続き、事故等のない施工に心がけて、まちづくりを進めていきたいというふうに考えているものです。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"同じく公園整備事業で、東品川公園についてと。時間があれば、３４７ページの大崎駅周辺地区の再開発で、大崎エリアマネジメントについて伺いたいと思います。例えば幅員５.５ｍの生活道路について、これは、ここの警視総監が答弁で言っているとおり、道路管理者である品川区、または地域住民からの要望があれば、交通管理者である警察に働きかけをしていただけるのかどうか、この辺についてお伺いします。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０の件についてお答えいたします。ゾーン３０につきましては、生活道路、こういったところで、歩行者や自転車の安全を確保するということを、交通安全の対策の１つということで、推し進めているところです。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"今回の具体的な対策によって、一歩前進、手が打てるなという感じがするのですけれども、これは、どういう優先順位でこの４３カ所、先ほど若干の説明はありましたけれども、どんなに危険であっても、あくまで私有地であって、この中では、その４３カ所の場合は上限５００万円、３分の１のマックスのですから、１,５００万円以上の工事。","respondent":"鈴木建築課長","answer":"それから自然斜面が組み合わさったもの。こういったものを４３カ所のうちから抜き出して、アドバイザー派遣等を使って、働きかけをして、助成につなげていきたいというものです。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３つ挙げます。最後に、クジラの滑り台ということです。私、個人的にそういうの大好きなものですから。さて、この３種類の生き物の造形物について、共通点があるのですが、それについて公園課のほうで教えてください。同じ造形物、タコ公園を除いて、今、かなり真似されていますが、レディーメードのものがあるのか、それともこれはオーダーメードの１点ものなのか、それについて教えてください。","respondent":"溝口公園課長","answer":"今回、委員ご紹介いただきました神明児童遊園のタコ、または子供の森公園の怪獣、または東品川海上公園のクジラ、いずれにしましても、この共通点という形になりますが、ある１つのそういった造形の遊具等をつくるメーカーがありますので、そちらのほうに一貫して。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いろいろ、その後、変遷はあったのですけれども。それが再評価されてもいいかと思います。ですから、こうした品川区が有する、大人までを魅了するデザインを使った造形物、これは、全てはそうではないと思うのですね。これ、外国の方がタコを見たら、これはびっくりしますよ。ですから、この不思議な造形美を、ぜひシティプロモーションとして活用していただきたいと思うのですが、いかがでしょうか。","respondent":"中島企画部副参事","answer":"そのような形で、ちょっと手応えは感じているところですが、そういう遊具、オブジェは、今の子育て世代のみならず、当時、今の大人の区民の方にとっても、行ったことがあるとか、愛着があるものだと思いますので、区外への発信とともに。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと地元要望です。１点だけ要望です。リニューアルによって様々なご意見もあると思うのですが、以前のベンチ数が、大分、ベンチの数が減ってしまいまして、お散歩中の高齢者の方が、座る場所が減ってしまったというご要望を受けております。昨年リニューアルしたばかりで、非常にちょっと心苦しいところがあるのですが、これはぜひ対応はしていただきたいと思いますが、いかがでしょうかというところ。","respondent":"溝口公園課長","answer":"今後も、地域の方、またはご利用者の方の声を聞きながら、ベンチの設置、そういったものは考えていきたいというふうに考えているものです。続きまして、トイレの関係です。公衆便所、公園・児童遊園便所、合わせまして。","id":"exchange-048"},{"speaker":"吉田委員","kind":"確認","question":"３１９ページ、１項土木管理費、１目土木総務費、シェアサイクル事業、３５７ページ、６項住宅費、１目住宅総務費、東日本大震災支援費、被災者受入住宅費、３５８ページ、３目区民住宅費、伺いたいと思います。しかし、言うまでもなく、安全性の確保が大前提ということを改めて確認したいと思います。検討する必要があると考えるのですけれども、その辺はどうなっていますでしょうか。","respondent":"多並道路課長","answer":"私からは、まず自転車レーンの考え方についてお答えします。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、整備中と言うか、整備の途上にあると考えてよろしいのでしょうか。シェアサイクル事業は始まってしまいますので、それまでに、他区との連携も図られているように伺いましたので、それまでにきちんと整備されるように要望したいと思います。損害賠償の分も含めて入っていくということでいいでしょうか、確認させてください。","respondent":"多並道路課長、安井土木管理課長","answer":"勝島一丁目で整備した、今年度行った工事についても、この路面標示に従って整備したものです。今後もこのような形で、警視庁ともよく協議しながら進めていきたいという内容です。利用者のを別にかけるということではなくて、自転車そのもの、それぞれにかけていくというような形になろうかと思います。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。保険のほうは、全員、それで乗る人の分はカバーできると考えていいですね。レーンのほうなのですけれども、標示はわかりました。さっき、伺うのを忘れました。幅のとり方というのが、どうなっているのかなと。一律でも、品川区の場合、それは無理だよねという、そういう道もあるように思うのですけれども、その辺どうなのか、もう１回お答えいただけますか。","respondent":"多並道路課長","answer":"幅の件ですが、一定の幅員、１.５ｍとか、幅員がとれる道路であれば、警視庁と連携して、自転車の通行帯という規制をかけていくのですけれども、品川区の場合、なかなかそういう場所がないということで、車道の横を通っていく、そこの場所を通るのですよという。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"その辺のことも、シェアサイクル事業を始めるに当たっては、徹底をお願いしたいと思います。次に行きます。３５７ページの住宅総務費で、東日本大震災支援費の被災者受入住宅費と、東日本大震災支援費の中で住宅原状回復費ですね。それぞれ減額になっておりますので、減額の理由をお知らせください。それから合わせて、現段階で、東北から避難してきて品川区に住んでらっしゃる方の状況を教えてください。","respondent":"今井住宅課長、寺嶋木密整備推進課長、久保田総務課長","answer":"３５７ページ、東日本大震災支援費と、３５９ページの同じく支援費です。木密整備推進課で実施しています密集事業の中で従前居住者用住宅というものがございまして、３３９ページの下から６行目になります。内訳ですけれども、福島県が２９世帯７４人、宮城県が４世帯５人、岩手県が２世帯２人、茨城県が１世帯２人という状況です。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"国と福島県は、今月末、帰宅困難区域を除くすべての避難指示を解除して、原発事故避難者への住宅無償提供を終わらせようとしております。東京都は、該当者にヒアリングをしているのですが、品川区はこの状況を把握していらっしゃるのか、教えてください。福島県の調査では、この住宅支援費の打ち切り後、どうするのか決まっていない避難者が７割以上に上るということなのですが、品川区ではいかがでしょうか。","respondent":"今井住宅課長","answer":"初めに、現在、帰還を求められている方ですけれども、福島県のほうにつきましても、一定の避難指示区域以外の部分で、平成２９年３月末までに、住宅確保ができない特別の事情がある場合には延長するということになっておりますけれども、それ以外の対象の方が。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。それから、今回の無償提供を打ち切られる人以外にも、避難者の方がいらっしゃるということなわけで、そういう方たちの状況というのは、把握していらっしゃるのでしょうか。例えば先行きがなかなか決まらないで、不安定な立場の人が相談したいと考えたときに、品川区にはそれを受け止める窓口はあるのか、伺いたいと思います。","respondent":"久保田総務課長","answer":"私ども、区営住宅に入っている人以外から何かあれば、総務課なり、相談を受けまして、然るべき部署にも相談をということを考えているところです。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。もし何か見解があったら伺います。納付促進の費用が大変急増していて、どういう趣旨の急増かなということで伺いたいと思います。この状況を、何とか払えるようになっていただく、そのためには、品川区が、しごと応援センターですか、あそこで家計相談をしているので、その機能をぜひ活用してほしいな、その活用が生きているのかなという視点で質問しますので、よろしくお願いします。","respondent":"今井住宅課長","answer":"委員ご案内のとおり、暮らし・しごと応援センターなど、生活困窮者の自立支援相談窓口等ありますので、関係各課と連携しながら、相談等に対応していきたいと考えています。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は、暮らし・しごと応援センターで、家計相談、設置する必要がないのに始めたということを大変評価しております。その機能をぜひ有効に生かしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"３３１ページ、下水道管耐震化推進事業について、そして、その後に八潮地区まちづくり検討経費、立会川・勝島地区まちづくりビジョン策定費について伺います。下水道管です。大震災が高い確率で予想されています。合わせて、上水道についても知っている範囲で、この計画についてお答えいただきたいと思います。","respondent":"和田河川下水道課長","answer":"引き続き、災害復旧拠点、それから福祉避難所、保管避難所、マンホールトイレ設置公園の下水道の耐震化を進めておりますが、この災害復旧拠点等の耐震化も、平成２９年度に完了の見込みです。","id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"一般の住宅、そこのところが大事だし、大震災が発生したら避難所に逃げられるからいいのだというのではなくて、やはり、できれば自分の家で過ごしていきたい、そういうのは、誰でも共通する思いですから、きちんとした耐震化を進めていくという、そういう方向で捉えていただきたいというふうに思っておりますけれども、この一般住宅、東京都の資料もいろいろ見せていただいたときに、指導も含めて。","respondent":"和田河川下水道課長","answer":"下水道の耐震化ですけれども、先ほど私申しましたとおり、公共施設の耐震化については、ほぼ来年度終了するわけなのですが、今後、地区内残留地区を行った後、一般の下水道に順次展開していくということは、東京都も考えているところですが、先ほど申しましたとおり。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"もっと、ちょっといろいろ教えていただきたいところがありますけれども、次に行きたいと思います。それから、長寿命化や集約建替余剰地活用というふうな表現がありますけれども、集約建替余剰地活用というのは具体的にどういうことなのか、ちょっと教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"それから長寿命、また、この集約型ですけれども、これは今後、まちづくりの手法といたしまして、今、既存６９棟、様々な権利者がいる中で、建物の再編などは非常に難しいというところがありますけれども、ただ、長い将来を見据えた上では、１つはリフォームですとか。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"その中で集約をしていくと、そこは厳格にとっていただいて、進めていただきたいということを、ちょっと要望したいと思います。それから、ちょっと時間がなくなってしまったのですが、立会川・勝島のまちづくり、これについては、区は、課題に対応した今後のまちづくりの方針となるビジョンというふうにしていますけれども、どのような課題があるのか、まず区の課題の認識を伺いたいと思います。","respondent":"中村都市計画課長","answer":"そういったところが課題というふうに認識をしております。","id":"exchange-060"},{"speaker":"沢田委員","kind":"意見","question":"パーセンテージということで、何％済ということですけれども、実際、見ていても、何カ所か買収というか、買われたのだろうなというのがわかるところも何カ所か出てきましたけれども、２０２０年までということでしたけれども、相当それは難しい状況だなとは思いますが、実際、都のほうで、その土地をもう購入されて、今、買った場所がどうなっているのかなというところで、僕の見たところでは。","respondent":"中村都市計画課長","answer":"そういった意味からいたしますと、もうその１年から２年前には工事に着工しなければいけないというところを考えますと、実際に着工するまでには、かなり短い期間ということになると思います。","id":"exchange-061"},{"speaker":"沢田委員","kind":"質問・要望","question":"公園の防犯カメラですけれども、ちょっと前にも、去年も聞きましたけれども、今、品川区内の、去年の段階でですけれども、答弁の中では、１１の公園で３０台、防犯カメラが公園内に設置されているということですけれども、実際、その公園内で、事件とか犯罪とか、不法投棄とか、そういったことを、区内の公園の中で、今どういう状況、そういうことがあるのかどうか、実際の状況についてお聞かせください。","respondent":"溝口公園課長","answer":"実際、公園内での、ここ最近ですけれども、犯罪が起こっているという話は聞いておりません。ただやはり、いわゆる若者が騒ぐとか、そういった苦情は入っているものの、公園内で何か犯罪が起きて、防犯カメラが必要となったというようなケースは、ここ近年ではございません。","id":"exchange-062"},{"speaker":"沢田委員","kind":"質問・要望","question":"それなので、ぜひ積極的に、実際、地域での犯罪抑止につながっているという、この間の一般質問の中でも聞かせていただきましたけれども、区内の犯罪抑制には大変貢献しているということで、今の防犯カメラはずっと見ているわけではないですから、犯罪があったときに使うといった形ですので、ぜひ、こういった防犯カメラの設置というのは増やしていただきたいなと思います。","respondent":"溝口公園課長","answer":"ただ、やはり、今、通常でありますと、委員のお話にありましたように、これまでどおり、人による巡回警備、また、すぐ、即日に警備員が対応できるような対応をとっております。","id":"exchange-063"},{"speaker":"沢田委員","kind":"質問・要望","question":"今は、地域につけている防犯カメラのほうは、都からも助成がいっぱいありますけれども、今、公園につける分には、きっと区費だけでやってらっしゃるのかなと思うので、そのあたりも考えながら、あと巡回の警備にかかるお金とか、そういったことも予算を考えて、ぜひ整備していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"いながわ委員","kind":"質問・要望","question":"大体、窓口で、何となく後ろから聞いていると、言われているのが、区民である証明書ですから、免許証とか保険証とか、いろいろ出してくださいということで、本当にしながわ水族館に行こうと思って行く人は、そういうものをもしかしたら用意しているのかもしれないのですが、やはり、ふらっと行って、ああ、水族館があるのだという感じで来ると、そういうものを持ち合わせていない方もいる中で。","respondent":"溝口公園課長、鈴木建築課長","answer":"続きまして、ペンギンランドの改修、平成２９年度に予定しておりますが、今現在、ペンギンがアシカの水槽のところにいるところは、鳥インフルエンザ対策として、外に、屋外に置いておけないものですから、屋内にということで。それからアクションプログラムの策定状況ですが、こちら、午前中もご説明しましたように、何か冊子になって分厚い冊子になっているものではございませんで、国の補助を受けるに当たって、重点地区ですとか、あるいは戸別訪問の計画。","id":"exchange-065"},{"speaker":"いながわ委員","kind":"質問・要望","question":"しながわ水族館、しながわ区民公園に関しては、しっかりコンセプトを用いてつくっていただきたいと思います。それで耐震に関しては、ちょっと木密の今回のと絡めると、耐震の、今回、今、質問したものに関しては、助成額が増額をされる。やはり相乗効果で実績は上がっていくと思いますので、エリアの拡大ということを今後考えていただきたいと思いますが、いかがでしょう。","respondent":"鈴木建築課長","answer":"除却の区内全域への拡大のご質問ですが、まずやはり、木密地域の、木造の不燃化、これは何か方向が違うわけではなくて、地域の防災性の向上というところでは共通した内容ですので、まず除却については、本当に木密地域内の防災性の向上の観点から。","id":"exchange-066"},{"speaker":"塚本委員","kind":"確認","question":"初めに、３２３ページの道路点検システム導入費ということで、プレス発表のほうにも、これは詳しくというか、載っておりますけれども、この道路の維持管理に関わるいろいろなお話というのは、区民の方からよく伺うところでもありますので、こういった形で点検作業に力を入れていただけるというところでは、大変に歓迎したいというふうに思っているところです。この２つ、まず２点お伺いをさせてください。","respondent":"多並道路課長","answer":"頻度といたしましては、月１回は必ず巡回をしまして、また主要な道路につきましては、頻度の高いところは週２回行っているところで、今度新しく点検するシステムについても、このような頻度で行っていくというものです。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問","question":"この、いわゆる路面のでこぼこを、車で走って検知するという、このようなことで説明されておりますけれども、どの程度、でこぼこを検知するようなシステムなのか。もちろん、大きな、道路として支障を来すような穴などは、もちろん検知するのだと思うのですが、そうではない場合も含めて、どの程度のものを検知するものなのか、教えてください。","respondent":"多並道路課長","answer":"設定しながらやっていきたいというのが、どちらかと言うと、そういう形のものがやっていきたいという内容です。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。このデータを取ることによって、今、道路の状態が、ここちょっと傷んでいるねとか、ここはちょっとまだ直したばかりだけれども、意外とまずいのではないかとかいうのがわかってくると、そういう定期的な全面舗装みたいなことの計画にも生かしていけるのではないかと思うのですが、そういうお考えがあるかどうか、お聞かせください。","respondent":"多並道路課長","answer":"私たちも、段差を感知するという、いわゆるそこで対処しなければいけないものもありますけれども、その次の、改修にもう少し経過観察をしながらも、改修しなければいけない、そういうものも拾いながら、いわゆる改修時期も、数値化を１つの目安にしながらやっているところも。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"国が、こういった義務付けをして助成をしていこうというふうに定めた狙いというか、理由ですね、これをまず１つ伺いたいと思います。それから、今回プレスにも出ておりますけれども、１１地区がこの対象として定められたということで、対象が約４,０００棟ということですけれども、この地域内には、品川区内の木密地域というのは、似たような地域はほかにもたくさんあるかなというふうに思います。","respondent":"鈴木建築課長","answer":"倒壊危険度５の地区は、品川区内はございません。次に高い４地区が、この１１地区ですので、そこで重点的にやっていくというものです。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"その倒壊危険度を、１から５とあって、４だというふうに判定するわけですけれども、これはどうやって判定するのか。人が歩いて建物を見てとかなのか、何か違うデータ等があってなのかというところを、ちょっとお伺いしたいというのが１つと。４,０００棟に対してどういう形、全棟に対して１回戸別訪問をするぐらいの予算規模なのか、あるいは何回も何回も行けるような感じなのか。","respondent":"鈴木建築課長","answer":"戸別訪問のやり方、予算に対するやり方なのですけれども、基本的には、１軒１軒まずチャイムを押して訪ねて、いる方に、事業のＰＲですとか、耐震化の必要性、そういったところを説明しながら、簡単なアンケートもその場でとりたいというふうに考えてあります。","id":"exchange-071"},{"speaker":"塚本委員","kind":"提案","question":"わかりました。では、その委託の先ですね。これまでも、ちょっと似たような事業で、建築士事務所協会の協力をいただいたりとかしながらやっていたところがありますけれども、その委託先がどういうところになるのかというのをお聞かせいただきたいのと。地域的には、おそらくこの１１地区、かぶっていると思いますので、その点もいかがでしょうかということで、お伺いいたします。","respondent":"鈴木建築課長","answer":"木密地域、不燃化のエリアでもありますので、そういった戸別訪問もしております。区民の方から、耐震化なのか、不燃化なのかというご相談もいただいております。そういったところも、不安を解消しながら、しっかりＰＲを進めていきたいと思います。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"よろしくお願いをしたいと思います。ちょっと最後に時間があるので、１つだけお聞かせください。３３９ページ、可動式ホーム柵整備助成で、今年度、荏原町ということでございましたけれども、今後の予定等、何かあれば、一言だけお聞かせいただきたいと思います。","respondent":"中村都市計画課長","answer":"荏原町、来年度を予定しております。それ以降は、今、東急大井町線の中で下神明ですとか旗の台、そういったところも働きかけていきたいと考えております。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"それで、水神口のような形は、なかなかスペースがないので難しいかとは思いますけれども、やはり大きな突破口になるのではないかなというふうに思いますので、そういう考え方ではいかがでしょうかということについてのご見解をお聞きします。３つ目は、３５８ページの区民住宅です。フラット型は３棟あるということなのですが、１棟はファミーユ下神明、あと２棟の助成金の期間はいつになっているでしょうか。","respondent":"溝口公園課長、桑波田交通安全担当課長、中村都市計画課長、今井住宅課長","answer":"そういった中で、楽しんでもらえる、そういったものも含めて、デザインというかコンセプトを入れて整備を進めてきているというものです。今後につきましては、昨年の新聞報道等で、自転車活用推進法というのが、国会のほうで出されたということが発表がありましたので、そういったものの。そういった長いスパンの中で考えつつも、短期的なまちづくりの中で。建設型区民住宅のフラット家賃に対するお尋ねです。ファミーユ下神明につきましては、助成期間の終了期限が平成３０年２月。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"駐輪場の件ですが、いろいろな動向がある中で、さらに考えていただければと思いますが、大森周辺の駐輪場の状況がどうなっていくのかだけ教えてください。区民住宅のほうですけれども、これはどうするのですかね。だけど、ぶつっと切られた場合に、助成金がなくなるわけですから、相当金額が高くなるということになると思うのですね。それをどのように考えていくのでしょうか。","respondent":"桑波田交通安全担当課長、中村都市計画課長、今井住宅課長","answer":"大森駅周辺の駐輪場の整備状況ですけれども、大田区のほうについても、大田区側のほうに幾つか駐輪場のほうは整備されているところですけれども。これは非常に短期間のまちづくりの意見集約というわけではなくて、ある程度、一定程度の時間をかけて。フラット型家賃の１５年間終了に伴います対策についてですけれども、こちらのほうは、入居時。","id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問・要望","question":"３３７ページ中心に、水辺の利活用を伺います。それと、今出ていたので、３４１ページ、八潮地区のまちづくり、この辺をもう一度伺います。そういう中で、団地再生の実例調査を踏まえて、先ほど再配置を視野に入れながらということで、どんなことを、委託ですから、調査に当たっての、まず基本オーダー、こんなところが留意点であるよと、今までのご答弁以外であれば教えていただきたいと思います。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"そういった意味から、同じ、今まで要望が出てきた中でも、それが本当はどういう意味なのか、そういったところまで、さらに深く掘り下げる形で、皆様の意見をお伺いしながら進めてまいりたいと考えております。どんなオーダーをしていくのかですけれども、先ほども答弁したように、品川区内のいろいろな水辺のそれぞれの性格によって、どんな賑やかしができるかどうかということを、現状を踏まえて検討していきたいと考えています。","id":"exchange-076"},{"speaker":"渡辺委員","kind":"質問・要望","question":"八潮のところ。水辺のことを伺います。こんなところで舟運が１つ。この辺は、地域要望も多いと聞いていますので、拠点づくりの、今の内訳も含めた要望が結構あると思いますが、ぜひ検討いただきたいのが１つ。やはり足元を照らす中で、古風な、少しセンスのいいものというものもよく聞きますので、この辺も具体的に、区がリーダーシップをとって研究される必要性も含めて、お考えを伺えればと思います。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"そういった中では、建替えなども、これはまだ１５年、２０年単位で、実際、先のような話になります。他地区でもこういった団地の中で建替えを達成するまでに、２０年ほど検討に要したというところもあります。カヌーの拠点づくりと言いますか、艇庫等の設置ですけれども、これも地域の方々からご要望をいただいているところですので、水辺の拠点としてどこがふさわしいのか、検討してまいりたいと考えています。","id":"exchange-077"},{"speaker":"渡辺委員","kind":"質問・要望","question":"という、何となくストーリーがある中で、計画と実施の、もう一度、スケジュール観と言うのですかね、この構想の検討の後どう生かしていくか。これはやはり、地元、目黒川協議会、住民視点であり、あるいは利用者全体を踏まえて、何かを制約だけではなくて、とにかくマナーアップを中心に、大変強い要望があって、速やかに、この年度内、会議体が招集されて、この４月にということで。","respondent":"和田河川下水道課長","answer":"この舟運事業の試験、舟運の社会実験をやってきたわけなのですけれども、我々のやった社会実験は、区内の桟橋を自由に使っていただいて、ルートは事業者に考えていただくということで、先ほど申しましたように、２１７の運行をしたわけなのですけれども。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３４１ページの東急大井町線連続立体交差化事業と、３４９ページの戸越公園駅周辺まちづくり事業について、いろいろ伺いたいと思います。それに関わって、補助２９号線道路計画についても伺います。戸越公園駅周辺まちづくり事業についてですけれども、事項別明細書を見ると、沿道における再開発等の協働箇所を検討とあります。駅の北側と南側、それぞれ伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちら、五丁目１９番地区というところになります。こちらで再開発準備組合が立ち上がっているところです。駅の北側におきましては、ただいま、五丁目１０番地区におきまして、再開発等の勉強会等が行われているということで伺っております。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"その北側の五丁目１０番のところは勉強会ということですけれども、具体的な高さですとか、階数とか、用途というのは、わかりますでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"五丁目１０番地区につきましては、まだ勉強会です。具体的な高さ等につきましては、今後、地権者の中で詰めていくような形になります。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"明細書には、過年度の検討成果などを踏まえ、都市計画として誘導する方向性を、沿道まちづくり計画としてまとめるともあります。過年度の検討成果とは何か、誘導する方向性とは何なのか、この計画をいつまでに作成するのか、手続きなど、スケジュールも合わせて、それぞれ伺います。そして、北側のところの勉強会は、どんなことを検討しているのかも伺います。","respondent":"東野まちづくり立体化担当課長","answer":"再開発計画が進んでいるところにつきましては、その計画についての支援を行っていくです。勉強会等が行われているところにつきましては、そちらの情報を注視しながら、区としての支援を今後考えていきたいというふうに考えております。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"どういう検討をして、勉強会でやっているかというのもお聞きしたので、わかる範囲でそれをご答弁いただければと思います。過年度の検討成果もお聞きしましたので、伺いたいと思います。スケジュール観もぜひよろしくお願いします。","respondent":"東野まちづくり立体化担当課長","answer":"具体的に言いますと、平成２６年につくりました戸越公園駅周辺のまちづくりビジョン、こちらが過年度の検討の成果だと考えていますので、それらをもとにまちづくりを進めてまいりたいと思います。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"具体的に、戸越五丁目１９番の再開発についても伺いたいと思います。直近で事業化が予想されているということで、組合の認可や建物の解体・着工、完成などのスケジュールを伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"現在、協議・調整中ではありますけれども、平成２９年度都市計画決定を予定するということになりますと、大体、権利返還計画が翌年度、それから組合の認可につきましても、同じ平成３０年度が予定されます。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問","question":"計画内容はどうなっているでしょうか。階数、高さ、用途、延床面積、そして総事業費、補助金、公共施設管理負担金、委託会社を伺います。","respondent":"東野まちづくり立体化担当課長","answer":"階数ですけれども、地上２４階、地下１階建てになります。高さにすると約９０ｍになります。それから用途につきましては、住宅と店舗、店舗につきましては、１・２階部分に入れていきたいとのことです。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問","question":"事業化が予想されるということは、準備組合が今できていると思うのですけれども、この参加人数ですね。土地、建物、借家、借地などの権利者について、全体が何人で、何人が参加・加入しているのか伺います。先ほどの大成建設は、参加組合員ということでよろしかったでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"借家人につきましては、増減あるところなのですけれども、私どもに届け出がある範囲では７５人というふうに聞いております。先ほどの土地建物所有者、借地権者２１件のうち、１９件が今、参加を表明しています。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"この１９番の再開発と、補助２９号線はどう関係しているのかも伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"五丁目１９番のところの再開発の範囲につきましては、今、０.３ｈａほどありますけれども、補助２９号線のところに一部かかってあります。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"この１９番のところを、補助２９号線から立ち退かなければならない方の入居先にしようというお話もあるのか、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの五丁目１９番の再開発計画の１つのコンセプトとしまして、補助２９号線、またはほかの特定整備路線にかかる方の住居の受け皿としてつくっていきたいというようなことも聞いておりますので、そういう可能性があると思います。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"事項別明細書にも、補助２９号線によって、既存の商店街の分断や地域商業機能の低下など、課題が生じていることを認めています。まちを壊して、この超高層９０ｍを進めていくということは許せません。この商店街の分断で、住民にどういう影響を与えるのか伺います。地域商業機能の低下も、住民にどういう影響を与えるのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"ただ単純に危惧しているだけではなくて、今後のまちづくりを地域の中で考えていきたいというところで、この再開発計画も出てきたところです。区としては、そういったまちの声に対して、支援をしていきたいというふうに考えてあります。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"地域の方も危惧しているところで、この補助２９号線を、それが原因なわけですから、これをやめていけば、そういった課題はないわけでありまして、この補助２９号線を、そういった面からもやめていくべきだと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"これをいい機会と捉えて、この道路の整備を前提に、これからもますますまちをよくしていこう、そういった取組みの中で、協議会の方針として、今、地元の方々と、そして区と、また東京都が連携して進めているものです。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"この高さが９０ｍということで、戸越公園駅にこんな高い建物ができてしまうと、周りは大体５階までしかないですね。そんなところに超高層がふさわしいと思うのか、伺います。やはり、この駅周辺のまちは、親しみやすく、お店で日常会話を楽しんで、顔の見えるつき合いができる、こういったまちのよさがあると思います。この面からも、超高層はふさわしくないと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"この駅前の再開発につきましては、地元の皆様方がこのようにしたいという考えの中で、区としても支援をしているものです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"区がどう考えているかということもお聞きしましたので、これがふさわしいと思うのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"そういった中で、商店街の分断だとか、こういったものを前向きに受け入れられる地元の方々の意思を尊重して、これからも支援を最大限続けていきたいと、そのように考えているところです。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"私は、３１７ページの交通安全啓発費、それから３２７ページの道路バリアフリー事業、３２１ページ、ＬＥＤからの質問をいたします。そして、その下から６行目の、しながわ交通安全フェア、３３１万円余ですけれども、この事業は新規事業とのことですけれども、交通安全宣言から５０年ということでありますが、この事業の説明もお願いをしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"この事業の中で、今回、親子の自転車教室ということで、年間、毎年やらせていただいていますけれども、平成２９年度につきましては、また新たに区独自で安全教室を実施しようということで、２回ほど実施する計画を、予算を入れしています。","id":"exchange-092"},{"speaker":"木村委員","kind":"質問・要望","question":"そういうことが大変多くありますので、本当に警察、また行政としても、しっかりとまた監視をしていただきたいと思っています。次に、３２１ページの下にありますけれども、街路灯やＬＥＤについてです。蛍光灯、そして白熱灯、それから水銀灯とありますけれども、３種類の中からどれを取り除き、ＬＥＤに変えていくのでしょうか。その変えるわけというものもお聞かせを願えればと思います。","respondent":"多並道路課長","answer":"街路灯につきましては、国際条約の水銀に関する水俣条約に基づきまして、２０２０年までには水銀ランプ等の製造が禁止されるということを踏まえまして、平成３１年度までに、今の水銀灯をＬＥＤ化をしていくというのを、計画的に行っていこうというものです。","id":"exchange-093"},{"speaker":"木村委員","kind":"意見","question":"いずれ、区内の街路灯というのは、水銀灯はなくなるということですし、いつまでにこの水銀灯は全て、先ほど、平成３１年とかとおっしゃっていましたけれども、平成３１年に全てこの水銀灯がなくなるということでありますが、あと、それ以外の蛍光灯とか白熱灯、これらも全て交換をしていく予定なのかどうかというのもお聞かせください。","respondent":"多並道路課長","answer":"水銀灯をＬＥＤ化していくのは、平成３１年度までに進めてまいります。それ以降ですね。","id":"exchange-094"},{"speaker":"木村委員","kind":"意見","question":"このＬＥＤなのですけれども、家庭の中で、普通の生活の中でも十二分に使えるものなのかどうかということも、お聞かせください。","respondent":"多並道路課長","answer":"我々、街路灯でやっているものは、かなり大きい製品でやっているものなのですけれども、それ以外、民生品についても、電気会社に聞くところによると、かなりエネルギー効率が高いということで、環境課のほうでも一般家庭のほうに普及啓発しています。","id":"exchange-095"},{"speaker":"木村委員","kind":"意見","question":"３２７ページの上から２行目、道路バリアフリー事業ですけれども、大井町駅周辺バリアフリー工事、７,０００万円、計上されています。平成何年にこの大井町が終了するのか、そして、大井町が終われば、次はどこになるのかもお聞かせください。これは、高齢者の方々にとってみれば、大変なバリアになると思いますけれども、これはどうしてなのかもお聞かせください。","respondent":"多並道路課長","answer":"その中でも、短期でできるものについては、平成２７年から平成２９年の間、中期でできるものは、平成３１年度までということで、計画的に進めているものです。","id":"exchange-096"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３３９ページ、京浜急行線連続立体交差化、北品川駅前広場整備等検討委託について、お伺いをいたしたいと思います。その中で、今回発表された。それで、２、３階建ての店舗を並べていく。だから、これもオーダーを出すときに、そういうことも検討してくるよというオーダーがあっていいと思っていまして、そういう考えもオーダーの中に入れていただきたいと考えていますが、そのお考えをお願いしたい。","respondent":"東野まちづくり立体化担当課長","answer":"北品川の駅前広場につきましては、先般行われました京浜急行の連続立体交差化事業の素案説明会と合わせまして、地元のほうに説明をさせていただきました。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"提案","question":"本当にいいものになってほしいなと思っておりまして、渡辺委員が非常にいろいろ質問したので、私からは１つだけ、ここには水辺景観地区があって、都の屋外広告物条例、これに何でひっかかるのかよくわからないけれども、力士のあの絵が、もちろんわかっていますよ、大きさがどうのこうのというのはわかっているのだけれども、何でそれが。","respondent":"和田河川下水道課長","answer":"そういうものも勘案しながら、我々のこの構想のほうもやっていかなければならないというふうに考えてございまして、夢は夢で描きたいとは思っていますけれども、そういうところも心に置きながら、検討を進めてまいりたいというふうに考えてあります。","id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"質問","question":"みんな、それなりに詳しい人がいるから。それはもちろんわかっていますよ、お金を使って、税金を使って、例えば条例違反みたいなものを出していいのかというのは、もちろんそれはわかるけれども、そういうことも踏まえて、やはり両面で出してもらうということも、私は水辺の場合だったら、相当規制がかかっているから、ありかなと思うので、もう一度、ちょっと考え方を聞かせてもらっていいですか。","respondent":"和田河川下水道課長","answer":"そういう意味で、何が言いたいかと言いますと、課題は同じく持っていまして、東京都の舟運社会実験にも参画し、しっかりと議論を深めて、先ほど来からおっしゃっている東京都の条例も、彼らも崩していかなければならないという課題意識は持っているでしょうから。","id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"提案","question":"ぜひよろしくお願いします。それはいいのですが、そういうことで、では今度逆に、頭の片隅にあれば、そういう提案をして、例えば第四日野小学校の卒業生に記念で配るとか、その板を何枚もつくっておいて。そういう発想も持って、提案をして、そういう木札を残そうとかという、頭の片隅の案でいいので、地元の方と話すときに、そういう片隅を持っていてほしいなと思うのだけれども、考えをお聞かせください。","respondent":"多並道路課長","answer":"今の委員のご提案のとおり、やはり育ってきた学校の周辺でもありますし、やはり地元でも親しまれてきた桜ということですので、よくその辺は、地元もありますが、あと小学校も含めて幅広くご意見をお伺いして、有効活用できるのであれば図っていきたいと思うところです。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問","question":"区営住宅の、この長寿命化計画に関して、区営住宅の老朽化への対応という観点を、まずお聞きしたいと思います。こうした状況は区でも認識をされていると思いますけれども、こうした老朽化に対する対策、今後、具体的な方策をとっていくと思われますけれども、今後の、この老朽化への対策をどのように考えていらっしゃいますでしょうか。","respondent":"今井住宅課長","answer":"初めに、区営住宅の老朽化への対応ですが、こちらにつきましては、委員ご指摘のとおり、３５年以上経過している住宅、都営住宅からの移管住宅が多いということも踏まえまして、私ども、日常の管理を適切に維持管理するとともに、計画的に修繕を行いまして。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問","question":"国の制度化された老朽化の観点で長寿命化という策定指針が出た、それに基づいて区としても進めていきたいというお考えを伺いました。では、それを踏まえて今後、この老朽化とともに、やはり利便性を高めていくという、建物の１つ考え方があると思いますが、いわゆるバリアフリーの考え方ですね。かなり高齢化が高いというふうに予測しておりますけれども、区営住宅の高齢化がどのような状況かというのが１つ。","respondent":"今井住宅課長","answer":"やはり高齢化に伴いまして、一定の段差とか、そういうことに対しましては、手すりの設置ですとか、そういうもので対応してきたところですけれども、やはり今後、緊急の見守りのシステムなどもあるというところですので。","id":"exchange-102"},{"speaker":"こんの委員","kind":"提案","question":"二葉一丁目、ここの区営住宅。これに関しても、実は平成２４年のときに、エレベーターの設置をというふうに提案をさせていただいた際に、残念ながら耐震工事のときに、日影の問題でつけられませんというご答弁だったのです。その当時と今とでは５年経っていますので、状況が変わっているかもしれないですが、ここの住宅に関してのエレベーターの設置の可能性というのは、どのようにお考えでしょうか。","respondent":"今井住宅課長","answer":"私どもも、複合施設ですので、入居者の皆様だけではなく、ほかの利用者の方々の状況を考えながら、検討は進めて、今後も続けていきたいと考えています。","id":"exchange-103"},{"speaker":"こんの委員","kind":"質問・要望","question":"理由を改めて伺ったのですが、日影の問題で、感覚的に申し上げると、あの辺は密集をしていない、それこそ周りは、日影どころか、どこが日影の影響なのかというところもありますが、確かに複合施設ではあるのですけれども、住宅に上がる階段、ご存じかと思うのですが、ものすごく段差が高いのですよね、あそこ。両サイドにある階段が。ご答弁もう一言お願いいたします。","respondent":"今井住宅課長","answer":"複合施設であるということを踏まえて検討するとともに、私ども、区営住宅等につきましては、日常生活に著しい支障を来す場合には、住替えという形、区営住宅の中の住替え等もやっておりますので、例えば下の階、または別の住宅等への住替えなどについても。","id":"exchange-104"},{"speaker":"こんの委員","kind":"質問・要望","question":"２点目の、道路安全施設費ですけれども、こちらは先ほども質問が出ておりました、自転車推奨ルート整備ですけれども、南大井のここにするということですけれども、南大井、この桜新道は、もう早くから自転車レーンを、走行レーンをつけていただいているので、ここの中に設置をしているほかに、確認ですけれども、先ほどのご答弁でいくと、場所は、新たにできるところは。","respondent":"多並道路課長","answer":"予定ですと、その後に、今、委員のご指摘にあったような場所を、今後やっていこうというところで、考えています。ただ、ナビマークにつきましても、設置した後、警視庁と連携しながら、そこの有効性というのは検討していきたいと、やっていきたいと思っているところです。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"そちらの、今の４つの駅の駐輪場の稼働率と言うのでしょうか。駐輪場全体で結構ですので、その現状と、それから利用状況についてのご見解と、あと、ここの人口増加の中で、やはり駐輪場をご利用される方が増えていくと思われるのですが、それに対する今後の見通しについてお伺いいたします。","respondent":"桑波田交通安全担当課長","answer":"今後につきましては、それぞれ場所によって需要の必要、利用が全然違いますので、その場所、場所を含めまして、場所的な増設となればいろいろ難しいところもありますので、そういった需要を含めまして、民間を含めて。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問","question":"立会川のほうが８３％、あとシーサイドも、かなりマンションも多いということで、７４.９％ということであります。特に立会川は、勝島地域の方が増えた場合、こちらの駐輪場のご利用の方が増えると思われるのですが、ちょっと今、京急の下を使われているところですが、今、見通しで、少し探していくというお話でしたが、見通し的にはどのような状況でしょうか。","respondent":"桑波田交通安全担当課長","answer":"場所につきましては、いろいろ協議やお願い等もしています。民間も含めてやっているところです。近くの大森のほうも地下の駐輪場が開設いたしますので、そういったところも含めましてご案内して、ご利用いただくように進めていきたいと考えております。","id":"exchange-107"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほど来、ほかの委員の方からも出ていますが、立会川・勝島まちづくりビジョンというような、その中で、そこのビジョンの策定の中で、このような駐輪場、特に人口増加地域の駐輪場について、立会川・勝島まちづくりビジョン策定の中でどのような観点で計画案を立てていかれるのか、お教えいただきたいと思います。","respondent":"中村都市計画課長","answer":"このまちづくりのビジョン策定の中では、地区内での自転車ですとか、そういった利用については、当然考えていく必要があると考えていますが、ただ、その利用される方がさまざま、周辺の駅まで利用されるというところにおきましては。","id":"exchange-108"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、私、立会川と勝島のお話が出たので、それで先ほど青物横丁のお話がありました。立会川・勝島と、あと八潮に関しては、いろいろまちづくりの計画等が進められていますが、一般質問でもお尋ねしたのですが、マスタープランの中ではあまり具体的には出てきておりません。この人口増加について、東品川地区のまちづくりについて、改めて具体的にどのような取組みをなされるのか、お教えください。","respondent":"中村都市計画課長","answer":"勝島、八潮以外に、この東品川地区ですけれども、こちらのほうは今、四丁目で再開発が進められておりまして、このまちづくりマスタープランの中では、広域都市活性化拠点ゾーンということで、また、その周辺につきましては、産業居住環境調和ゾーンということで、現在。","id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"旧東海道の地域と、マンションの融合した地域、様々な商業施設もありますけれども、地域の方々が、今後この辺の東品川の地域をどういうふうにしていくかという、そういう話し合いの場を、あるいは勉強会みたいものを設置していただければというお声がありますので、これは要望としてお伝えしておきます。これらの５つの公園についてお尋ねします。そのためのスペースの確保もお願いしたいと思います。","respondent":"溝口公園課長、和田河川下水道課長","answer":"浜川公園につきましては、平成２９年度に設計を行っていきますので、そういった中で、どのような形で復旧していくのか、地域の声も聞きながら、検討していきたいというふうに考えているものです。月見橋の家の、現在、仮施設がある場所ですが、あれは東電から、浸水対策事業用地として買い上げまして、今、仮施設を建てているものですが、その後の用途につきましては、今後検討してまいりたいと思っているところです。","id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、課長もお話ししていただきましたが、地域の皆様の声を聞いて、それを反映させていただきたいと思います。バリアフリー以外は受託事業ということでありますので、様々な補助、受託事業でそれを使って、従前、あるいはそれ以上の公園にしていっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"提案","question":"私は、３２１ページ、道路維持管理、それから、３４１ページ、東急大井町線連続立体交差化事業、それから、３４３ページ、公園整備事業費に関連して質問します。その角の非常に目立つ場所にあるわけでありまして、１つの提案なのですけれども、例えば角の場所を品川区が借り入れをして、イメージは渋谷のスペイン坂スタジオってご存じでしょうかね。ご答弁をお願いいたします。","respondent":"多並道路課長","answer":"最初の国道については、わかりました。国道事務所と連携しながら進めてまいります。今のご提案につきましては、今後、事業を進めている中で、ご提案の趣旨も含めながら、可能なのかというのは、全体的な中の、総合的に検討してまいることだと思っているところです。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"提案","question":"公園整備事業ですけれども、これは、私たちも自民党で勉強する中で、しながわ水族館のことを随分と議論させていただきました。結果として、夜間の営業、それから様々なものの販売、それから夜の水族館やデートコース等々、いろいろな構想ができると思うのですが、構想として持っているのですが、いかがでしょうかという提案です。ご答弁をお願いいたします。","respondent":"溝口公園課長","answer":"今後の水族館のあり方、または運営の仕方、そういったものを考える際に、委員ご提案のものも含めて、どのような形でいけば一番いいのか、公園の管理も含めまして、検討していきたいというふうに考えているものです。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"提案","question":"そこがずっとネックになってきたのですよね。それが上がっていく可能性があるわけではないですか。その将来は、当然、この品川区民公園全体を考えていくこともあるでしょうし、水族館だって、毎年何千万円もかけて運営していくわけではないですか。そんなことを考えていくと、やはり、５年、１０年、計画を持って、こういうものを具体的に計画していったほうがいいと思うのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"そういったものも含めまして、今後の水族館のあり方というのは、運営しておりますサンシャイン、または近隣の方のご理解をいただきながら、十分検討していきたいというふうに考えているものです。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"今、思い出しましたけれども、この水族館、閉園も含めた議論、相当されたではないですか、内部の検討会をつくって。結果として、これは続けていこうと決めたわけですよね。やはり新しくリニューアルしていくことを考えていくと、そういう販売スタンドの複数化、それからベンチ、それから休憩する場所等の拡大も検討していくべきだと思うのですが、いかがでしょうか。ご答弁をお願いいたします。","respondent":"溝口公園課長","answer":"外の販売車、または昼食等、皆さんが食べられるベンチとか、そういう休憩施設につきましても、レストランも含めまして、どういった形でお客様に楽しんでいただけるのか、そういったところも含めまして、平成２９年度に少し検討していく費用も予算化しておりますので。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問","question":"例えば大崎だったか、社会実験で移動販売車をやったではないですか、そうですよね。だから、確かに検討することはもちろん必要、やってほしいけれども、でも、あれだけやはり日曜や土曜日のことを見ていくと、１カ所の販売スタンドしかないわけだから、それはなかなか利用者にとってどうなのかなという思いがあるので、短期的には、そういう移動販売車等の活用をすべきと思うのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"今後も、水族館利用者の方に満足いただけて、またリピーターとして水族館に来ていただける、そういった取組み、できることから着実に進めていきたいというふうに考えているものです。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"私も一般質問でこのことを提案させていただきました。それからあと、小学校や中学校の数も、将来足りなくなってくるということを考えていくと、やはりこのまちのあり方はもっと検討すべきということを提案させていただいたのですが、現時点で品川区はどういうふうな検討の方向性と、それから構成メンバーとスケジュール観をお持ちなのでしょうか、お答えをください。お願いいたします。","respondent":"中村都市計画課長","answer":"そういった中では、この増える人口の中で、どうやって住みやすいまちをつくっていくかというところになります。そういった意味からいたしますと、生活施設ですとか、あるいは公共施設、こういったものの方向性についても含めて検討していく必要があると考えております。","id":"exchange-117"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、３４７ページの大井町駅周辺地区再開発事業と、３５９ページの区営住宅について伺いたいと思います。大井町駅周辺地区再開発事業の広町地区整備検討委託について伺いたいと思います。そしてもう１個、単独検討業務委託は、誰が何を検討するのか。そして、どこにこれも委託されるのか、伺いたいと思います。６,０００万円という大きな金額ですので、詳しく教えてください。","respondent":"稲田都市開発課長","answer":"それからもう１つ、単独検討ですが、これは１,５００万円、これは区の検討です。この機会に合わせまして、区の庁舎の再配置の検討や、また導入施設等がどういうものが考えられるのか、そういうところを検討していきたいというふうに考えております。","id":"exchange-118"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません、どこに委託をそれぞれされるのか、伺いたいと思います。それと、大井プレイス構想での、ここの広町の位置づけなども伺いたいと思います。","respondent":"稲田都市開発課長","answer":"委託先につきましては、来年度、決めていくということになります。ＪＲとの共同検討におきましては、ＪＲと協議しながら、また決めていくということになっていきます。広町地区におきましては、まちづくりの、大井プレイス構想等あります。","id":"exchange-119"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"委託先がまだ決まっていないということなのでしょうか。それなのに、これだけ６,０００万円という金額だけが決まっているというのが、ちょっとわからないのですが、そこを伺いたいと思います。やはり、大井プレイス構想、具体化ではなくて、住民参加で住民が望むまちづくりを進めていただきたいと思いますけれども、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"委託先ですが、やはりこれはＪＲとの協議を、今後詰めていくというところでございまして、それによって決めていくです。大井町、広町、これもまちづくり構想がありますので、これに沿った形で考えていくです。","id":"exchange-120"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ちょっとここは引き続き聞いていきたいなと思いますので、今はいいです。それで、次に、区営住宅についてですけれども、この区営住宅の浴槽、風呂釜の設置や撤去について伺いたいのですけれども、区営住宅は現在１３団地、事務事業概要では１３団地４３９戸ということでいいのか、ちょっと確認させていただきたいのと。そして、設置していない世帯があるのか、伺いたいと思います。","respondent":"今井住宅課長","answer":"そのうち、今現在は、都営から移管されました西五反田五丁目の１３、１４号棟２棟、それから区のほうで設置しました西大井六丁目第三、それから、西中延が、こちらのほう、改築いたしましたので、こちらということで、全部で今４棟につきましては、４棟１２４戸につきましては。","id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、設置費用や撤去費用を把握されていない。区営住宅は、要は所得が低い人が入っているのに、この自己負担はとても厳しいと思わないかどうか、区の見解を伺いたいと思います。ですので、その辺の把握もしていただいて、これが厳しくないと思うのかどうかをちょっと伺いたいのですね。ぜひ、区営住宅も、区の責任で設置していくと言うことに踏み込んでいくべきだと思うのですけれども、いかがでしょうか。","respondent":"今井住宅課長","answer":"初めに、自己負担の問題ですけれども、区営住宅に新たに入居する方を対象に、区の負担で浴槽等を設置する考えは、現在のところございません。建替えを行っていく中で、浴室の設置を含め、バリアフリー化を進めていく考えです。","id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問","question":"公社住宅も、中堅所得者向けというふうに、今おっしゃられましたけれども、しかし、居住者も高齢化し、年収も今どんどん下がりつつあって、平均年収３００万円に満たないという状況だそうです。それで、中堅層の住宅には当然ついていると。そうすると、低所得者の住宅にはつかなくてもいいということなのでしょうか。その要件の１つに浴室があります。区にもこの目標はあるのか、伺いたいと思います。","respondent":"今井住宅課長","answer":"こちらの公営住宅等長寿命化計画、平成２５年のほうで策定させていただきましたけれども、こちらのほうでも、今、実際に、西中延、そして中延一丁目と、建替え等を進めているところですので、今現在、風呂釜の設置について、区負担で設置する考えはございません。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、私は、最低居住面積水準、これに対しての区の目標があるかということを伺いました。そこをお答えいただきたいと思います。ですので、こうした面からも、区営住宅のこの自己負担で、もしつけられていない世帯があれば、まるでこの水準を満たしていない住宅を、区が提供しているということになるのではないでしょうか。ぜひ目標を持って、計画を持っていただきたいと思いますけれども、いかがでしょうか。","respondent":"今井住宅課長","answer":"住生活基本法等で、国のほうの目標で行っております面積については、１人当たり２５m2というところで、面積が決められておりまして、また、１人ずつ増加している中で、一定の面積が配分されているものです。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問","question":"浴槽について、私、伺ったので、ぜひそこに答えていただきたかったのですが、残念です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"３３８ページ、都市計画費に関して、公共交通についてちょっと。それから、３５６ページの住宅費。それから、時間があれば、３３５ページの目黒川障害物調査について伺いたいと思います。これは、誰が何のために、どこからどこへ、そしてどんな交通手段を使っているかという調査をしているそうですけれども、こういう調査も合わせて活用しているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"区内の交通につきましては、これは品川区のみではなくて、その周辺区、また都内全域に関わることでございまして、先ほど委員からご紹介いただきましたパーソントリップ、これは東京都が調査を行っておりますが、これが目的別、あるいはその規模、こういったものを。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"今のはパーソントリップ調査を参考にして計画を立てているという答弁ですので、どんな計画があるのか教えていただきたいと思います。そこで、関連して３２５ページの補助１６３号線のＪＲ大崎支線ガード下、今回新たに計上がされました。そこで、この延長１００ｍと、幅員１６ｍということだそうですが、この目的と成果について、今の私のデータの分析も参考にしながら、ご説明をいただきたいと思います。","respondent":"多並道路課長","answer":"ここ最近の例で言いますと、都市計画道路の単体でやるというよりは、どちらかと言うと、都市開発をこの周辺でやる場合に、この道路計画というのを一緒に行いながら検討しているデータがあります。","id":"exchange-127"},{"speaker":"若林委員","kind":"質問・要望","question":"補助１６３号線について、目的と、特に成果、ここをしっかりとご答弁いただきたいと思います。大崎と大井、ここをつなぐ、いわゆる今まで、ある意味でネックと言われていて、いわゆる路線バスがなかなか法律上通れない、こういう課題がありましたので、そこはしっかりとご答弁を。","respondent":"多並道路課長","answer":"今後の、副都心である大崎と、区の中心である大井町をつなぐ、一番重要な幹線道路でもありますので、ここのボトルネックの解消に向け、早期整備を進めたいということで、平成２９年度も予算計上させていただいたところです。","id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"この補助１６３号線、ＪＲ大崎支線ガード下の工事進捗によって、こういった課題の１つが大きく進展をするというふうに理解をしますので、頑張っていただきたいと思います。","respondent":"和田河川下水道課長","answer":"五反田リバーステーションが、オリンピック・パラリンピックまでにできるということで、舟運が活性化することが見込まれます。","id":"exchange-129"},{"speaker":"若林委員","kind":"質問・要望","question":"しっかり進めていただきたいと思います。そういうものを撤去することによって、ちょっとこれは素人考えですみません、いわゆる満潮時は、橋と、その水面の高さが非常に狭まって、一定の大きな船だと通れないという課題もあると思うのですが、その川底、浚渫も含めて、除去することによって、少しかさが上がるかということは、あるのでしょうか。","respondent":"和田河川下水道課長","answer":"喫水の関係で、それはございません。","id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"大きく４点聞いていきたいと思います。３点目、４項都市計画費、４目都市開発費、３４９ページ、都市防災まちづくり事業に関連して、イトーヨーカドー戸越店跡地について、再度伺いたいということ。これの面積がどれぐらいあったのかということと、これを直すに当たって、近隣との折衝というか、トラブルがなかったかどうか、その辺をまずお聞きしたいと思います。","respondent":"多並道路課長","answer":"地元の件ですけれども、やはり今までご利用いただけなかった所について整備するということですので、１軒１軒お話しさせていただいて、ご了解をいただきながら工事を進めたです。","id":"exchange-131"},{"speaker":"松澤委員","kind":"意見","question":"公共溝渠は、広い所は、今のように道路として活用する。そして、狭い所は売却するというような方針になっていると思うのですけれども、これは、どれぐらいの広さだったら道路として開放していくのか。そしてまた、道路として開放するだけの広さがありながら、このように囲い込まれている土地というのはどのぐらいあるのか、その辺、お知らせいただければと思います。","respondent":"安井土木管理課長","answer":"現在、公共溝渠と言われる部分は、法定外公共物という位置づけでございまして、大体２.５ｍ未満の狭い所というようなことになってあります。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"今の説明、わかりました。大変でしょうけれども、開放できる所は開放する努力をしていただきたいと思います。意識はしていなくても、不法占拠していることになりますので、その辺のことをしっかりと言っていただきたいと思うのですけれども。なおかつ、２軒にまたがっている、当然そうですよね、境ですから。この辺、何か要件が緩和されているということはあるのでしょうか、その辺をお聞きしたいと思います。","respondent":"安井土木管理課長","answer":"あるいは、片方はこれはもう必要ないということであれば、もう片方の方に、その面している部分を全部買っていただくというような個別の話を、それぞれに行いながら、不法占有の解消、そちらのほうを対応していると。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"丁寧なご答弁、ありがとうございました。大井三丁目の方からの話なのですけれども、自分の家の境、公共溝渠があるのだけれども、品川区が測量をしに来たと言うのですね。立ち会いを求められたと言うのですけれども。これはどういうことなのですかね。今の話ですと、公共溝渠は、買いたい人が、自分たちで測量するということなのですか。その辺、お聞きしたいと思います。","respondent":"安井土木管理課長","answer":"私どもとしては、不法占用の早期解消ということで、測量を積極的に、区のほうで負担いたしまして、さらに、測量するということで、不法占有の状態にあるということをご認識いただくということで、少しでも不法占有の解消を進めるという形で、事業を進めてあります。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"最近、そのようなことが耳に入ったものですから。わかりました。２点目に行きたいと思います。平成２７年１１月１３日の請願第２７号、上大崎シルバーセンターに隣接した空家の土地を品川区で取得することに関する請願。他人、ほかの方がいるものですからね。これについて、その後、どのような形で、地権者の方にお話をして、交渉が進んでいるのでしょうか。お聞きしたいと思います。","respondent":"今井住宅課長","answer":"本請願につきましては、採択を受けまして、平成２８年の一定のときに、区として処理経過につきましては、空き家対策や公共施設の有効活用の観点から、総合的に検討してまいりますということで、処理経過を差し上げたものです。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問・要望","question":"対応しているというお話を伺いましたけれども、これはできれば、手紙でも何回でも送って、区は買う意思がありますよということを、常にお伝えをしていただければというふうに思っています。３点目にまいります。都市防災まちづくり事業に関連して、イトーヨーカドー跡地をもう一度伺います。区や地元が要望している店舗というもの、改めて見つかったのでしょうか。お聞きしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"同店跡地につきましては、解体工事前の地盤調査を先行して行うというふうに聞いております。店舗探しにつきましては、歳入でもお話ししましたとおり、立地上、収益性上から、難航しているというふうに聞いてあります。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"歳入で質問の際に、区が借りることも検討しているというお話を伺いました。私は、こういう民間のものを、トラブルがあったときに区が借りるというのは反対ですよというお話をしたのですけれども、どんな検討をしているのか、この辺をちょっとお聞きしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"店舗が見つからないという場合に備えまして、地元のほうからの要請もありますので、全部賃貸マンションにするよりも、地域にある行政ニーズに応えられるためのスペースを区が借りまして、施策展開していくというところを検討しています。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"そこでちょっと伺いたいのですけれども、商店街が近い上に、昨今の保育事情などを考えると、小規模認可保育所や、あるいは在宅で子どもを育てる方たちのための子育て支援、オアシスルームみたいなものが、子どもを預けた親たちが、帰りに商店街に立ち寄って買い物をするというものも、これは賑わいにつながるのではないかなというふうに思っているのですが、この辺はいかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"区が借りる場合につきましては、地域需要を踏まえまして、区としての施策展開ということになりますので、委員ご提案も含めまして、担当所管とも調整してまいりたいと思います。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。これで止めておきたいと思います。４点目です。３４５ページ、戸越公園管理棟建替基本設計委託について、８５０万円。公園の管理棟などというのは、もう、今、直営でやっているわけではないので、要らないのではないかという声もありますけれども、なぜこれが基本設計委託、直すのでしょうか。あるいは何か、直してほかの使い方というものを考えているのでしょうか、その辺お聞きします。","respondent":"溝口公園課長","answer":"一応、今後の計画になりますが、保育園の仮園舎とか、そういったところの利用、または環境としていろいろ展示ができたりとか、啓発ができる、そういったものも合わせて併設していきたいというふうに考えているものですので。","id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、これは、管理棟のこちら側に車庫もありますから、それを含んでの大きな敷地というふうに考えたほうがいいのでしょうかね。保育園等の建替えのときという話を今、伺いましたけれども。荏原第四中学校の跡地に、今後２つですか。保育園に変えてやっていくということなので、それでは建て替える期間が足りないということで、ここにしましょうということなのでしょうか。","respondent":"溝口公園課長","answer":"戸越公園のところにつきましては、一応、今のところ、予定で行きますと、三ツ木保育園の改修に合わせて必要なものということで聞いているところです。","id":"exchange-140"},{"speaker":"松澤委員","kind":"質問","question":"三ツ木保育園の改修に合わせて、そこに仮園舎をつくる。それはいいのですけれども。それについて、この建物そのものが、プレハブ的につくって、また新たに直していくのか、あるいは恒久的な施設としてやっていくのか、その辺が本当に重要になると思うので、その点についてお聞きしたいと思います。","respondent":"溝口公園課長","answer":"ただ、今後どういう形で、それ以降使っていくのかというのも、合わせて検討していきたいというふうに考えているところです。","id":"exchange-141"},{"speaker":"松澤委員","kind":"質問","question":"プレハブ式ですと、やはり、またやり直すのではもったいないですから、その後の使い道も考えて、恒久的につくってもらいたいということと。あるいは、車道におりてくるということで、これは事故につながらないかなというふうに思っているのですが、あれを立てたのは、当然、品川区でしょうから、その点の考え方というのを聞いておきたいと思います。","respondent":"多並道路課長","answer":"ただ、更なる安全対策ということで、もう少し様子を見ながら、また警視庁とも連携しながら、またよりよい形があるのであれば進めていくところなのですけれども、なかなかハード的な対策というところですと、なかなか限界があるのかなというのは感じているところです。","id":"exchange-142"},{"speaker":"藤原委員","kind":"意見","question":"３５９ページ、借上型区民住宅、これは特優賃の状況をお願いします。それともう１つ、３３５ページ、河川費になるかもしれないのですけれども、なぎさ会館の工事のところの壁に、オリンピック・パラリンピックの競技の写真が大きく飾られていますが、これはどういう経緯でああいう形になったか、お答えください。","respondent":"今井住宅課長、和田河川下水道課長","answer":"今後ですが、平成３０年度に１住宅、平成３１年度に１住宅、それぞれ返還いたしまして、平成３１年度には、この地優賃の住宅はゼロという形になります。このたび、２月末に、この設計変更の設計が完了いたしまして、３月いっぱいで家屋調査を行い、４月に工事を再開する見込みというふうに、下水道局から聞いているところです。","id":"exchange-143"},{"speaker":"藤原委員","kind":"質問・要望","question":"住宅課長、整々粛々とルールにのっとってやってください。それと、あと、オリンピック・パラリンピックのパネルの件なのですけれども、品川区内にいろいろな壁がありますけれども、これは企画調整かもしれないのですけれども、その壁、いっぱいあると思うのですけれども、何か活用して、オリンピック・パラリンピックでしていくのでしょうか。これはトイレですか、便所ですか。これの確認が１点。","respondent":"柏原企画調整課長、溝口公園課長","answer":"そういった区が持っている施設を有効活用するというのは、これは大きな効果があろうというふうに思ってありますが、景観の問題であったりとかありますけれども、なるべくそういうところをうまく使いながらということで。臭いの対策ですが、これまでも、清掃をこまめにやるというのが一番有効だというふうに考えております。そういった中で、全てのトイレを１回、利用者が多い所については２回、清掃しています。","id":"exchange-144"},{"speaker":"藤原委員","kind":"質問","question":"区は、このスポーツの動向の高まりをどう捉えているのでしょうか。これからスポーツ行政が、特に東京のオリンピック・パラリンピック以降にどう反映させていくのか、お考えを教えてください。これについてちょっとお伺いしたいのですけれども、この便所に関して、どう臭いを感じられているのか、教えていただけますか。","respondent":"小川オリンピック・パラリンピック準備課長、立川経理課長","answer":"１点目の、オリンピック・パラリンピック大会を契機としたスポーツの高まりにつきまして、お答えします。すみません、庁舎のトイレの話ということで、私から答弁します。現在、庁舎には、無洗浄式便器というのを導入しておりまして、ちょっと女性の委員の方はぴんと来ないと思いますので、ちょっと導入の経過等を説明します。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、ようやくそこまで認めてくれたと思って。前回のときは、芳香剤の匂いがして、とてもいい匂いだという答弁だったので、ようやくわかっていただけたと思うので。何か答弁があればいただきたいのですけれども。この土木部門とスポーツ部門、それとオリンピック・パラリンピック部門という形で、それぞれ、その公園に関してお答えをいただけますか。","respondent":"立川経理課長、溝口公園課長、小川オリンピック・パラリンピック準備課長","answer":"トイレにつきましては、昨年の予算特別委員会でご指摘を受けまして、すぐできる対策といたしまして、今回の予算でも増やしていただいたのですけれども。今後も引き続き、オリンピック・パラリンピック準備課、またはスポーツ推進課、しっかり連携して、オリンピックを迎えたいというふうに考えているものです。そういった部分で、ハード・ソフト部門の連携が、十分図られているです。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"せっかくスポーツ推進課長が出てきてくださったのですから、スケートボードができるわけですから、オリンピック・パラリンピック部門が代表しないで、スポーツ推進課長も答弁をお願いします。","respondent":"池田スポーツ推進課長","answer":"今、オリンピック・パラリンピック準備課長が申し上げましたように、３課連携いたしまして、スポーツにつきましては、これから、誰でも、いつでも、そして、どこでも、ということ、これ１つを目標にいたしましてやっていきたいと思いますので、皆様、どうぞ公園施設。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"せっかくいい答弁に水を差してしまうかもしれないのですけれども、全庁挙げてやるのですよね。３課だけではなくて、全庁挙げてやるのですから、３課中心に、全庁挙げてやっていただきたいと思います。私も、２０２０、オリンピック、大成功することを祈って、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"あべ委員","kind":"質問","question":"３３１ページの月見橋の家等復旧。そして、３５５ページの、がけ安全化支援についてお伺いしたいと思います。これまでどのような対策を取ってきたのか、抜本的な対策はあるのか、今後何か打つ手はあるのか、そういったことを改めてお伺いしたいと思います。ただ、午前中のご答弁では、２１７便で１,３００人と聞こえたのですけれども、これは１便当たり６人という数字になるのでしょうか。","respondent":"桑波田交通安全担当課長、和田河川下水道課長、柏原企画調整課長、稲田都市開発課長、鈴木建築課長","answer":"それで、前回の、昨年行われました会議のほうにおきまして、東京湾岸署のほうから、大井ふ頭のいろいろな関係するところと、車両が止まらないように。舟運につきましては、採算がとれるかどうかとご心配だと思うのですけれども、先ほどの私の、２１７便で約１,３００人という数字ですけれども。もともと、こちら、南大井三丁目児童遊園というところでしたので、基本的な考え方は、やはり以前。再開発組合とともに、区も、今後も粘り強く交渉していくです。","id":"exchange-149"},{"speaker":"あべ委員","kind":"質問・要望","question":"こういったところが大規模修繕をしていくというようなことと、セットで考えることは、ではあり得るのかということについて、お伺いしたいと思います。それと、ちょっと先ほどお伺いし忘れたのですけれども、大崎駅の周辺ということで言えば、御殿山小学校西側の交差点から、ソニー通りにかけての道というのが、まだ狭い状態に、あそこだけ残っていることになっております。動き出す可能性はあるのでしょうか。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"４３カ所以外の、助成対象となる方々への周知ですが、基本的には、やはり、それ以外、区内全域が、道路沿いであれば対象になりますので、区のホームページ、あるいは広報しながわで周知をして。そういう中で、今年もニューシティの事務局とは何回も話をしてきたのですけれども、委員おっしゃったようなことも話をしましたけれども、それは難しいというような回答を得ております。","id":"exchange-150"},{"speaker":"あべ委員","kind":"質問","question":"御殿山小学校西側の道については、もし、スケジュール的な目途があれば、教えていただければと思います。それと、橋の話なのですけれども、ＴＯＣは星薬科大学とも絡んでいるのですよね。この交渉が難航している背景に、放射第２号線の話もあるとお考えでしょうか。","respondent":"稲田都市開発課長","answer":"私どもとしては、それは関係ないというふうに思っております。","id":"exchange-151"},{"speaker":"飯沼委員","kind":"質問","question":"３３９ページの特定整備路線沿道まちづくり、３４３ページのトイレ改修工事について伺います。よろしくお願いします。初めに、特定整備路線のまちづくりなのですけれども、事業の内容を簡単に教えてください。続いて、公園トイレのほうもいきます。性的マイノリティーに特化してのトイレということで、質問をいたします。紹介します。一刻も早く、ＬＧＢＴ対応のトイレ、必要と考えますが、いかがでしょうか。","respondent":"中村都市計画課長、島袋人権啓発課長","answer":"特定整備路線沿道まちづくり推進費ですけれども、こちら、東京都が進める道路の整備に合わせまして、延焼遮断帯の形成のために、その道路の沿道の用途地域を、火災に強い建物を建てていただくための防火の規制を。国や都の動向を踏まえた上で、関係部署との連携をとり、対応をしてまいりたいと考えております。","id":"exchange-152"},{"speaker":"飯沼委員","kind":"質問・要望","question":"飛び火は、３０ｃｍ以上の木片から、細かな火の粉まで、１４０ｍ以上の距離を飛んでいます。住宅建替えは、耐震化、不燃化、そして公園づくりなどに、住民の願いに、切実なところに応えるべきと思いますが、いかがでしょうか。トイレの改善の検討をしていただきたいと思います。今日はトイレのことで言いましたけれども、ぜひ区役所に、ＬＧＢＴの指針づくりなど検討会の設置を求めますが、いかがでしょうか。","respondent":"中村都市計画課長、島袋人権啓発課長","answer":"合わせて、耐震化のほうも、品川区内で取り組んでおりますので、委員ご指摘のところも含めて、進めてまいりたいというふうに考えております。検討組織のことですが、今のところ、私どものほうには、その方たちからのご要望・ご相談がないので、立ち上げる考えはございません。","id":"exchange-153"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご要望・ご意見が届かないというところに、ぜひ、この間も質問したのですけれども、声が届かないというのは、見ようとしなければ見えないのですね。そういった意味で、ＬＧＢＴのところ、特に遅れているので、力を入れていただきたいと思います。道路先にありきでは、住民の願いはかないません。道路ごり押し、やめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-154"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３２３ページの道路修繕、下村踏切前。同じく３２３ページの自転車推奨ルート整備に関連しまして。次に、３２５ページの細街路拡幅整備事業に関連して。それから最後に、３５７ページの空き家等対策事業でお伺いします。それから、細街路の拡幅に関連してですが、本会議の代表質問で、ブロック塀対策についてお伺いをしまして、その際に、区長から、周知については個別に説明をしていきますと。","respondent":"多並道路課長、鈴木建築課長、今井住宅課長","answer":"ただ、その法律の中で、市町村も計画を定めるというところなのですけれども、それには、東京都の計画を踏まえ。これは地域内、精力的に回っていただいているのですけれども、作成したチェックリストですとかパンフレットをお渡しして、ブロック塀の啓発も。空き家ホットラインにつきましては、現在、その相談業務のほかに、有効活用を目指しまして。","id":"exchange-155"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ぜひ、なるべくなら、この梅雨とか台風シーズン前に対応してもらえればありがたいなと思うので、そこだけご見解をお聞かせください。それから、自転車についてはわかりましたが、本当に活用ですね。もちろん安全対策も、また保険の話も出ておりましたけれども、そういうものも合わせて活用ということで、しっかりその辺の計画も、国や都の動きと合わせてしっかり連動してお願いしたいなと、これは要望します。","respondent":"多並道路課長、今井住宅課長","answer":"私からは、下村踏切の件ですが、もちろん１日でも早く工事をやりたいところなのですけれども、ただ、あそこの地下に、ＪＲの高圧ケーブルが埋まっているということもありますので、そこの協議がどうしても必要ですので、それを整え次第。現在のところ、月・水・金、都市整備公社のほうで、実際に電話またはメール、ファクス等で受けておりますけれども、今後も周知等に努めていくとともに、先ほど申しました各関連団体のほうにも、こちらのほうは周知しておりますので。","id":"exchange-156"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は、都市計画費から３３８ページ、まちづくり関係。３４７ページ、大井町駅周辺地区再開発、広町関係です。建築費で３５３ページ、住宅・建築物耐震化支援。それから３２０ページ、道路橋梁費で、道路維持費。これは全部、今までの質問に絡んできています。この辺も十分チェックしていただけないかなと思いました。この辺のところで、東品川のあの一画の関係をどう捉えていくのか、その点を教えてください。","respondent":"多並道路課長、中村都市計画課長","answer":"今後も、そういうようなものを踏まえながら、より道路のＩＣＴに向けた活用ができないかということを検討していきたいとは思っているところです。その周辺地域におきましても、今、事務所から住宅、あるいは倉庫から住宅といった、そういった利用の転換なども進んできておりますけれども、こういったところは、居住とそれから産業、こういったものが調和をしていくような。","id":"exchange-157"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"道路のほうは、私たちだったら、まだ対応できると思います。そういう方が、そういうでこぼこでけがをしないように、ぜひ注意のほうをしていただきたいと思います。昨年のときには、まだ診断していないところがあるよと聞いていたのですが、そこがどうなったのかを教えてください。何かと言うと、オリンピックに向けて、ここの土地をどういうふうに交渉するかという、その辺の検討はされているのでしょうか。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"そうしたところから、平成２３年より取組みを進めているところですが、沿道対象建物が２０４棟ございまして、そのうち、診断を終了したのが、すみません、まだ診断を行っていない建物が１０棟というような状況です。平成３０年１２月には解体工事が完了するということで、その後の利用についてですが、区としては、ここの暫定期間においては、利用は今のところは考えてはいないのですが、オリンピック・パラリンピックに向けまして、区の要望等あれば。","id":"exchange-158"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"耐震です。診断だけではなく、やはり緊急輸送道路ということを考えると、耐震化しておいてもらわなければいけないし、診断だけではなく、進めていっていただきたいということで、これはお願いします。広町です。これは課長でいいのか、区として今後どう考えるかというのは、まだ検討していないところを無理やりやってくれと言いにくいところなのですけれども、どう考えたらいいのでしょうか。","respondent":"稲田都市開発課長","answer":"確かに、建物が解体されていくと、広い土地ができるですが、ＪＲはＪＲで、この暫定の間、何らかの活用は考えているというふうに思われます。ただ、そういう中におきましても、区としての要望は伝えていきたいというところに考えております。","id":"exchange-159"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前のとき、平成３２年以降の検討、長期的なものですね。やはりこの、ＪＲはＪＲかもしれないけれども、品川区として、せっかくあれだけ積極的にオリンピックに取り組んでいこうという思いの中で考えると、ぜひＪＲにもっと働きかけをして、ここを、オリンピックのときにすばらしい施設ができる、人の集まってもらえる場所にするべきだと、私は考えるのですが、あえてもう一言お答えいただけないでしょうか。","respondent":"柏原企画調整課長","answer":"ＪＲのほうの建物が解体されて、大きな敷地ができるというところであります。本格的な活用は検討ということではあるのですけれども、これだけ大きな土地が出るというのは、なかなかないというのは事実です。","id":"exchange-160"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２３区の中でも、駅前にこれだけの土地ができるというのは、まずないと思うので、ぜひ成功に向けて頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-161"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/697202?Template=document&Id=1064#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":133282,"voices":401}}]);
